const FN_8019F420: usize = 0x8019_F420;
/// `0x801ACF80` - clear an OSContext-sized (0x2D4) buffer.
const FN_801ACF80: usize = 0x801A_CF80;
/// `0x801ACD40` - make a context current / restore one.
const FN_801ACD40: usize = 0x801A_CD40;
/// `0x801AC470` - data-cache flush over a byte range.
const FN_801AC470: usize = 0x801A_C470;
/// `0x801AC440` - data-cache invalidate over a byte range.
const FN_801AC440: usize = 0x801A_C440;
/// `0x800046B4` - `memset`-shaped wrapper; Ghidra drops its arguments.
const FN_800046B4: usize = 0x8000_46B4;
/// `0x801B5F80` - `OSGetTime`, returning a 64-bit time-base value.
const FN_801B5F80: usize = 0x801B_5F80;
/// `0x801A2B10` - per-frame helper taking a DMA/period argument.
const FN_801A2B10: usize = 0x801A_2B10;
/// `0x801A2270` - refresh the JAS parameter tables.
const FN_801A2270: usize = 0x801A_2270;
/// `0x801D5720` - write the DSP mailbox word.
const FN_801D5720: usize = 0x801D_5720;
/// `0x801D56E0` - read the DSP mailbox busy bit (bit 15 of `0xCC005000`).
const FN_801D56E0: usize = 0x801D_56E0;
/// `0x801A00E0` - release completed JAS objects.
const FN_801A00E0: usize = 0x801A_00E0;
/// `0x801A08F0` - large per-frame JAS helper (not translated).
const FN_801A08F0: usize = 0x801A_08F0;
/// `0x801A0E90` - JAS mixer; fills one 0x180-byte block.
const FN_801A0E90: usize = 0x801A_0E90;
/// `0x801A25B0` - read the word at `r13 - 0x5068`.
const FN_801A25B0: usize = 0x801A_25B0;
/// `0x801A3370` - return the next 0x38-byte trace slot, or 0.
const FN_801A3370: usize = 0x801A_3370;
/// `0x801A1CE0` - configure the DSP task at [`JAS_DSP_TASK`].
const FN_801A1CE0: usize = 0x801A_1CE0;
/// `0x801D5880` - start/queue the DSP task.
const FN_801D5880: usize = 0x801D_5880;

// ===========================================================================
// Small local helpers
// ===========================================================================

/// Calls a function that returns a `u32` in `r3` with no arguments.
///
/// The crate's [`crate::platform::call0`] discards the return value, which the
/// interrupt primitives and pointer-returning helpers need.
///
/// # Safety
/// `addr` must be a PowerPC function with this ABI.
#[inline]
unsafe fn call0_u32(addr: usize) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn() -> u32);
    f()
}

/// Writes a big-endian 64-bit value as two words.
///
/// # Safety
/// `addr..addr+8` must be writable.
#[inline]
unsafe fn write_u64(addr: usize, value: u64) {
    write_u32(addr, (value >> 32) as u32);
    write_u32(addr + 4, value as u32);
}

/// 8-byte-aligned storage for one PowerPC `OSContext` (724 bytes).
///
/// The original handler reserves `auStack_2d8`; the extra alignment matches the
/// ABI expectation of the context helpers and is not part of the size.
#[repr(align(8))]
struct AlignedContext([u8; 0x2D4]);

/// Reads a big-endian 64-bit value stored as a high word followed by a low
/// word, the inverse of [`write_u64`].
///
/// # Safety
/// `addr..addr+8` must be readable.
#[inline]
unsafe fn read_u64(addr: usize) -> u64 {
    ((read_u32(addr) as u64) << 32) | read_u32(addr + 4) as u64
}

/// Evaluates `a >= b` on 64-bit values the way the original compiler does.
///
/// The PowerPC has no 64-bit compare. The original emits `subfc` / `subfe`
/// with both high words XORed by `0x8000_0000` and then inspects the final
/// carry; that is exactly a signed 64-bit comparison, which this helper names.
#[inline]
fn signed_ge(a: u64, b: u64) -> bool {
    (a as i64) >= (b as i64)
}

// ===========================================================================
// AI/DSP bring-up, 0x8019F0B0..0x8019F420
// ===========================================================================

/// Replaces the AI/DSP interrupt callback and returns the previous one.
///
/// The callback word is `r13 - 0x5190`. The swap runs with interrupts disabled
/// so the DSP handler cannot observe a half-written pair.
///
/// # Original
/// - Ghidra: `FUN_8019f0b0` at `0x8019F0B0` (68 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8019f0b0_FUN_8019f0b0.c`
/// - `// observed:` the C reads the old word, calls `0x801B1140`, stores the
///   new word, then calls `0x801B1180`; Ghidra drops the restore argument.
///
/// # Arguments
/// - `callback`: new callback address, or 0 to remove it.
///
/// # Returns
/// The previous callback address.
///
/// # Side effects
/// - stores `callback` at `r13 - 0x5190`;
/// - disables and restores external interrupts.
///
/// # Safety
/// The callback must be a function with the AI/DSP handler's ABI when non-zero.
///
/// # Confidence
/// high - the swap and return value are explicit; only the restore token is
/// reconstructed from the call shape.
pub unsafe fn fn_8019f0b0(callback: u32) -> u32 {
    let previous = read_u32(SDA_IRQ_CALLBACK);
    let state = call0_u32(FN_801B1140);
    write_u32(SDA_IRQ_CALLBACK, callback);
    platform::call1(FN_801B1180, state);
    previous
}

/// Programs the audio-DMA source address and byte length.
///
/// The 32-bit address is split across `0xCC005030` and `0xCC005032`; the
/// length is converted to 32-byte blocks in `0xCC005036`. Each register keeps
/// the bits owned by the other half of the original value:
///
/// * high: keep bits 13..15 of the old register, replace address bits 16..28;
/// * low: keep address bits 29..31 of the old register, replace bits 5..15;
/// * control: keep the start bit, replace the block count.
///
/// The source address therefore must be 32-byte aligned, and the low five
/// address bits are not representable.
///
/// # Original
/// - Ghidra: `FUN_8019f100` at `0x8019F100` (124 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8019f100_FUN_8019f100.c`
/// - `// observed:` the C contains the three read-modify-writes shown below,
///   bracketed by `0x801B1140`/`0x801B1180`.
///
/// # Arguments
/// - `src`: main-memory source address of the block.
/// - `len`: transfer length in bytes.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the three audio-DMA registers at `0xCC005030`, `0xCC005032` and
/// `0xCC005036`, with interrupts disabled.
///
/// # Safety
/// Only meaningful on hardware/emulator with the DSP block mapped; `src` must
/// be a readable, 32-byte-aligned MEM1 buffer.
///
/// # Confidence
/// high - exact masks and shifts are observed.
pub unsafe fn fn_8019f100(src: u32, len: u32) {
    let state = call0_u32(FN_801B1140);
    write_u16(
        AUDIO_DMA_START_HI,
        (read_u16(AUDIO_DMA_START_HI) & 0xE000) | (src >> 16) as u16,
    );
    write_u16(
        AUDIO_DMA_START_LO,
        (read_u16(AUDIO_DMA_START_LO) & 0x001F) | src as u16,
    );
    write_u16(
        AUDIO_DMA_CONTROL_LEN,
        (read_u16(AUDIO_DMA_CONTROL_LEN) & 0x8000) | (len >> 5) as u16,
    );
    platform::call1(FN_801B1180, state);
}

/// Returns the "AI/DSP initialised" word.
///
/// [`fn_8019f1f0`] sets the word to 1 after installing the DSP handler; the
/// value 0 therefore means the block still needs bring-up.
///
/// # Original
/// - Ghidra: `FUN_8019f1e0` at `0x8019F1E0` (8 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8019f1e0_FUN_8019f1e0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `*(u32 *)(r13 - 0x51C8)`.
///
/// # Side effects
/// None; one word read.
///
/// # Safety
/// None beyond the target's normal memory map.
///
/// # Confidence
/// high - single load.
pub unsafe fn fn_8019f1e0() -> u32 {
    read_u32(SDA_AI_INIT_DONE)
}

/// Initialises the AI/DSP block and derives the five audio timing scales.
///
/// The function is one-shot: it returns immediately when the word at
/// `r13 - 0x51C8` is already 1. Otherwise it:
///
/// 1. calls the version/registration helper `0x801AB1C0`;
/// 2. reads the bus clock at `0x800000F8` and divides it by 500000;
/// 3. stores five zeroed scratch words and five scale words
///    (`bus/500000 * k / 8000`, for k = 0x7B24, 0xA428, 42000, 63000, 3000);
/// 4. clears AI volume and interrupt timing;
/// 5. when AI control bit 6 is clear, masks the control word, runs the DMA
///    calibration [`fn_8019f490`], sets bit 6, and restores the old control
///    value;
/// 6. clears the callback, stores the callback argument, installs
///    [`fn_8019f370`] on interrupt 5, unmasks `0x04000000`, and marks the block
///    initialised.
///
/// `// unknown:` the scale words are used as floats by `0x8019D480` /
/// `0x8019EDB0`, but their physical unit is not named in the image. Their
/// 64-bit `(scratch:scale)` pairs are the classifier input of [`fn_8019f490`].
///
/// # Original
/// - Ghidra: `FUN_8019f1f0` at `0x8019F1F0` (384 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8019f1f0_FUN_8019f1f0.c`
///
/// # Arguments
/// - `callback_arg`: word stored at `r13 - 0x5194` and tested by the handler;
///   0 selects the no-argument callback path.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// - writes ten small-data words, AI volume/timing/control, and the AI init flag;
/// - installs an interrupt handler and unmasks interrupt bit 26;
/// - calls [`fn_8019f490`], `0x801AB1C0`, `0x801B1140`, `0x801B1180`,
///   `0x801B11B0` and `0x801B1590`.
///
/// # Safety
/// Hardware/emulator only; the handler address must remain valid for the life
/// of the process.
///
/// # Confidence
/// medium - all writes are observed; AI control bit roles and the timer unit
/// are inferred from the register map.
pub unsafe fn fn_8019f1f0(callback_arg: u32) {
    if read_u32(SDA_AI_INIT_DONE) == 1 {
        return;
    }

    platform::call1(FN_801AB1C0, read_u32(SDA_AI_VERSION_PTR));
    let bus = read_u32(OS_BUS_CLOCK);
    let tick = bus / 500_000;

    // observed: the five zero words and the five computed words are stored in
    // an interleaved order; keep that order so a later reader sees the same
    // intermediate states.
    write_u32(SDA_AI_SCRATCH_0, 0);
    write_u32(SDA_AI_SCRATCH_1, 0);
    write_u32(SDA_AI_SCRATCH_2, 0);
    write_u32(SDA_AI_SCRATCH_3, 0);
    write_u32(SDA_AI_SCRATCH_4, 0);
    write_u32(SDA_AI_SCALE_0, tick.wrapping_mul(0x7B24) / 8000);
    write_u32(SDA_AI_SCALE_1, tick.wrapping_mul(0xA428) / 8000);
    write_u32(SDA_AI_SCALE_2, tick.wrapping_mul(42000) / 8000);
    write_u32(SDA_AI_SCALE_3, tick.wrapping_mul(63000) / 8000);
    write_u32(SDA_AI_SCALE_4, tick.wrapping_mul(3000) / 8000);

    write_u32(AI_VOLUME, 0);
    write_u32(AI_INTR_TIMING, 0);

    let mut control = (read_u32(AI_CONTROL) & 0xFFFF_FFCA) | 0x20;
    if (read_u32(AI_CONTROL) >> 6) & 1 != 1 {
        // observed: 0xFFFFFF8A clears bits 0, 2, 4, 5 and 6; 0x20 raises bit 5.
        write_u32(AI_CONTROL, (read_u32(AI_CONTROL) & 0xFFFF_FF8A) | 0x20);
        let state = call0_u32(FN_801B1140);
        fn_8019f490();
        write_u32(AI_CONTROL, read_u32(AI_CONTROL) | 0x40);
        platform::call1(FN_801B1180, state);
        control = read_u32(AI_CONTROL);
    }
    write_u32(AI_CONTROL, control);

    write_u32(SDA_IRQ_CALLBACK, 0);
    write_u32(SDA_IRQ_CALLBACK_ARG, callback_arg);
    platform::call2(FN_801B11B0, 5, fn_8019f370 as *const () as usize as u32);
    platform::call1(FN_801B1590, 0x0400_0000);
    write_u32(SDA_AI_INIT_DONE, 1);
}

/// DSP interrupt handler: acknowledges the DSP, runs the registered callback,
/// and restores the interrupted context.
///
/// The handler clears bits 5 and 7 and sets bit 3 of the DSP control/status
/// halfword. It clears a 0x2D4-byte OSContext-sized stack buffer, makes that
/// buffer current, invokes the callback when one is installed and not already
/// running, then restores `interrupted_context`.
///
/// The callback receives no argument when `r13 - 0x5194` is zero. Otherwise the
/// original routes through `0x8019F420`, the stack-switch trampoline; Ghidra
/// drops the argument to that call, so the callback address is passed in `r3`
/// here (`// unknown:` confirmed only from the trampoline's signature).
///
/// # Original
/// - Ghidra: `FUN_8019f370` at `0x8019F370` (168 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8019f370_FUN_8019f370.c`
///
/// # Arguments
/// - `_param_1`: first interrupt-frame word; unused in the recovered C.
/// - `interrupted_context`: context pointer restored at the end.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// - read-modify-writes `0xCC00500A`;
/// - clears two OSContext buffers and switches the current context;
/// - may call the callback and `0x8019F420`.
///
/// # Safety
/// Must run at interrupt level with a valid `interrupted_context`.
///
/// # Confidence
/// medium - the flow is explicit; the context helpers and the trampoline
/// argument are inferred from their shapes.
pub unsafe fn fn_8019f370(_param_1: u32, interrupted_context: u32) {
    write_u16(
        DSP_CONTROL_STATUS,
        (read_u16(DSP_CONTROL_STATUS) & 0xFF5F) | 0x0008,
    );

    let mut context = AlignedContext([0u8; 0x2D4]);
    let context_ptr = context.0.as_mut_ptr() as u32;
    platform::call1(FN_801ACF80, context_ptr);
    platform::call1(FN_801ACD40, context_ptr);

    let callback = read_u32(SDA_IRQ_CALLBACK);
    if callback != 0 && read_u32(SDA_IRQ_IN_CALLBACK) == 0 {
        write_u32(SDA_IRQ_IN_CALLBACK, 1);
        if read_u32(SDA_IRQ_CALLBACK_ARG) == 0 {
            call0_u32(callback as usize);
        } else {
            // unknown: Ghidra prints `FUN_8019f420()` with no argument; the
            // trampoline's own C takes the code pointer in r3.
            platform::call1(FN_8019F420, callback);
        }
        write_u32(SDA_IRQ_IN_CALLBACK, 0);
    }

    platform::call1(FN_801ACF80, context_ptr);
    platform::call1(FN_801ACD40, interrupted_context);
}

