/// Clamps a level to 0x8000 and stores it in the first 16-bit level slot.
///
/// # Original
/// - Ghidra: `FUN_801a18f0` at `0x801A18F0` (24 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a18f0_FUN_801a18f0.c`
///
/// # Arguments
/// - `level`: requested level; values above 0x8000 are clamped.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Stores the low halfword at `r13 - 0x512A`.
///
/// # Safety
/// None beyond normal memory access.
///
/// # Confidence
/// high - unsigned clamp and store are explicit.
pub unsafe fn fn_801a18f0(level: u32) {
    let clamped = if level > 0x8000 { 0x8000 } else { level };
    write_u16(SDA_JAS_LEVEL_0, clamped as u16);
}

/// Per-frame JAS update: timestamp, mix into a DMA block, mailbox handshake,
/// DMA kick, and optional trace copy.
///
/// The function is the heart of the output driver. In order it:
///
/// 1. stores `OSGetTime()` at `0x8037BFA0`;
/// 2. reads the audio-DMA bytes-left register;
/// 3. calls `0x801A2B10` with 0 (mode 1) or 0x5F50 (other modes);
/// 4. refreshes the parameter tables (`0x801A2270`), sends the DSP mailbox
///    command `0xBABE0080`, waits for the busy bit to clear, then sends the
///    scratch block returned by [`fn_801a0e60`] and waits again;
/// 5. releases completed objects and calls the large helper `0x801A08F0`;
/// 6. records four more time stamps around the optional per-frame callback;
/// 7. advances the 0xB4-slot ring at `0x8037BFE0` (four 0x168-byte buffers),
///    calls the mixer `0x801A0E90` for the next 0x180-byte DMA block, and in
///    two-buffer mode programmes the DMA immediately with [`fn_8019f100`];
/// 8. snapshots the counter at `r13 - 0x5068` and copies 0x40 bytes of the
///    timing state into the next trace slot.
///
/// `// inferred:` `0xBABE0080` is the DSP command word (the upper half is the
/// ASCII-looking marker `0xBABE`); the exact command meaning is not documented
/// in the image. `// unknown:` the ring is consumed by the mixer `0x801A0E90`,
/// which is outside this pass.
///
/// # Original
/// - Ghidra: `FUN_801a1940` at `0x801A1940` (608 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a1940_FUN_801a1940.c`
/// - `// observed:` Ghidra re-stores several 64-bit timing words unchanged at
///   the end (`0x8037BFA0`/`0x8037BFA8`); those no-op stores are documented
///   here but not emitted.
///
/// # Arguments
/// None.
///
/// # Returns
/// `(0x60 - (bytes_left >> 2)) * 0xED5`, a signed frame-remainder estimate.
/// `// unknown:` the unit; the arithmetic is reproduced exactly.
///
/// # Side effects
/// - writes the timing words at `0x8037BFB0..0x8037BFD0`;
/// - sends two DSP mailbox words and polls `0xCC005000` bit 15;
/// - updates the ring cursors and the DMA-block cursor;
/// - may program the audio DMA and call the per-frame callback;
/// - may copy 0x40 bytes into a trace slot.
///
/// # Safety
/// Hardware/emulator only; the mixer expects the ring and DMA buffers to be
/// initialised by [`fn_801a1dd0`].
///
/// # Confidence
/// medium - the control flow and all stores are observed; the DSP command and
/// ring units are inferred.
pub unsafe fn fn_801a1940() -> i32 {
    write_u64(JAS_TIMING_A, platform::call_u64(FN_801B5F80));
    let bytes_left = fn_8019f1a0();

    if read_u32(SDA_JAS_MODE) == 1 {
        platform::call1(FN_801A2B10, 0);
    } else {
        // unknown: 0x5F50 is passed only in the non-1 mode; its unit is not
        // recovered from the image.
        platform::call1(FN_801A2B10, 0x5F50);
    }
    platform::call0(FN_801A2270);

    let scratch = fn_801a0e60();
    platform::call1(FN_801D5720, 0xBABE_0080);
    while call0_u32(FN_801D56E0) != 0 {}
    platform::call1(FN_801D5720, scratch);
    while call0_u32(FN_801D56E0) != 0 {}

    platform::call0(FN_801A00E0);
    write_u64(JAS_TIMING_B, platform::call_u64(FN_801B5F80));
    platform::call0(FN_801A08F0);
    write_u64(JAS_TIMING_C, platform::call_u64(FN_801B5F80));
    write_u64(JAS_TIMING_D, platform::call_u64(FN_801B5F80));

    let frame_cb = read_u32(SDA_JAS_FRAME_CB);
    if frame_cb != 0 {
        call0_u32(frame_cb as usize);
    }
    // observed: the C copies the same 64-bit word back to JAS_TIMING_D here;
    // that is a no-op and is not emitted.

    write_u64(JAS_TIMING_E, platform::call_u64(FN_801B5F80));

    let write_index = read_u32(SDA_JAS_RING_WRITE);
    let mut next = write_index.wrapping_add(0x12);
    let routes = [
        (JAS_RING_A as u32).wrapping_add(write_index.wrapping_mul(2)),
        (JAS_RING_B as u32).wrapping_add(write_index.wrapping_mul(2)),
        (JAS_RING_C as u32).wrapping_add(write_index.wrapping_mul(2)),
        (JAS_RING_D as u32).wrapping_add(write_index.wrapping_mul(2)),
    ];
    if read_u32(SDA_JAS_RING_SIZE) <= next {
        next = 0;
    }
    let read_index = read_u32(SDA_JAS_RING_READ);
    if write_index <= read_index && read_u32(SDA_JAS_RING_READ) < write_index.wrapping_add(0x12) {
        write_u32(SDA_JAS_RING_READ, next);
    }
    write_u32(SDA_JAS_RING_WRITE, next);

    let dma_index = read_u32(SDA_JAS_DMA_INDEX);
    platform::call3(
        FN_801A0E90,
        JAS_MIX_CONFIG as u32,
        (JAS_MIX_BUFFER as u32).wrapping_add(dma_index.wrapping_mul(0x60)),
        routes.as_ptr() as u32,
    );
    let advanced = dma_index.wrapping_add(1);
    write_u32(SDA_JAS_DMA_INDEX, advanced);

    if read_u32(SDA_JAS_MODE) == 1 {
        write_u32(SDA_JAS_DMA_INDEX, advanced % 3);
    } else {
        let index = advanced & 1;
        write_u32(SDA_JAS_DMA_INDEX, index);
        fn_8019f100(
            (JAS_MIX_BUFFER as u32).wrapping_add(index.wrapping_mul(0x60)),
            0x180,
        );
    }

    write_u64(JAS_TIMING_F, platform::call_u64(FN_801B5F80));
    write_u32(JAS_COUNTER, call0_u32(FN_801A25B0));

    let trace = call0_u32(FN_801A3370) as usize;
    if trace != 0 {
        for i in 0..0x40 {
            write_u8(trace + i, read_u8(JAS_TIMING_A + i));
        }
    }

    // observed: the trailing C re-stores JAS_TIMING_A and JAS_TIMING_B with
    // their current values; no state changes, so the copies are omitted here.

    (0x60u32.wrapping_sub(bytes_left >> 2).wrapping_mul(0xED5)) as i32
}

/// DMA-completion callback: advances the JAS driver by one block.
///
/// When the task-active latch is not 1, the state at `r13 - 0x50D8` selects the
/// action:
///
/// * state 1 - clear it and run [`fn_801a1940`] (mix the next block);
/// * any other state - set it to 2 and start the DSP task at `0x8037CD00`
///   through `0x801D5880`.
///
/// In three-buffer mode it then programmes the block at cursor
/// `r13 - 0x50D4` and advances that cursor modulo 3 unless it would collide
/// with the mixer cursor.
///
/// # Original
/// - Ghidra: `FUN_801a1ba0` at `0x801A1BA0` (176 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a1ba0_FUN_801a1ba0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// May mix a block, start the DSP task, program the DMA, and write the two
/// cursors.
///
/// # Safety
/// Hardware/emulator only; must run as the DMA-completion callback installed
/// by [`fn_801a1dd0`].
///
/// # Confidence
/// medium - state values and cursor update are observed; the DSP-task call is
/// opaque.
pub unsafe fn fn_801a1ba0() {
    if read_u32(SDA_JAS_TASK_FLAG) != 1 {
        if read_u32(SDA_JAS_DMA_STATE) == 1 {
            write_u32(SDA_JAS_DMA_STATE, 0);
            fn_801a1940();
        } else {
            write_u32(SDA_JAS_DMA_STATE, 2);
            platform::call1(FN_801D5880, JAS_DSP_TASK as u32);
        }

        if read_u32(SDA_JAS_MODE) == 1 {
            let index = read_u32(SDA_JAS_DMA_INDEX_B);
            fn_8019f100(
                (JAS_MIX_BUFFER as u32).wrapping_add(index.wrapping_mul(0x60)),
                0x180,
            );
            let next = index.wrapping_add(1) % 3;
            if next != read_u32(SDA_JAS_DMA_INDEX) {
                write_u32(SDA_JAS_DMA_INDEX_B, next);
            }
        }
    }
}

/// Frame-boundary callback: mixes the next block when the driver is in state 2.
///
/// State 2 means "waiting for a completed update". The function clears it, runs
/// [`fn_801a1940`], and calls the optional frame-end callback at
/// `r13 - 0x5108`. Any other state is moved to 1 (waiting for the first
/// update).
///
/// # Original
/// - Ghidra: `FUN_801a1c60` at `0x801A1C60` (84 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a1c60_FUN_801a1c60.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the state word, may mix a block, and may call the frame-end callback.
///
/// # Safety
/// Must be called from the JAS driver's frame path with initialised buffers.
///
/// # Confidence
/// medium - state machine is explicit; the callback role is inferred.
pub unsafe fn fn_801a1c60() {
    if read_u32(SDA_JAS_DMA_STATE) == 2 {
        write_u32(SDA_JAS_DMA_STATE, 0);
        fn_801a1940();
        let callback = read_u32(SDA_JAS_FRAME_END_CB);
        if callback != 0 {
            call0_u32(callback as usize);
        }
    } else {
        write_u32(SDA_JAS_DMA_STATE, 1);
    }
}

/// Initialises the JAS output driver and starts the first DMA block.
///
/// Zeroes the three working areas (0x480, 0x300 and 0x5A0 bytes), flushes them,
/// configures the DSP task through `0x801A1CE0`, installs [`fn_801a1ba0`] as
/// the AI/DSP callback, primes the ring cursor at slot 0x12 of 0xB4, fills both
/// initial mixer configurations through `0x801A0E90`, sets the DMA state to 1,
/// programmes the first 0x180-byte block, and sets the DMA start bit.
///
/// The `mode` argument is stored at `r13 - 0x50F8`. `// inferred:` mode 1 uses
/// three DMA blocks and the second cursor; every other value uses two blocks
/// and the mixer cursor.
///
/// # Original
/// - Ghidra: `FUN_801a1dd0` at `0x801A1DD0` (504 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a1dd0_FUN_801a1dd0.c`
///
/// # Arguments
/// - `mode`: output mode; 1 selects the three-buffer ring.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// - zeroes `0x8037C880` (0x480), `0x8037C580` (0x300) and `0x8037BFE0`
///   (0x5A0), then flushes the ranges;
/// - writes the driver state, cursors, mode and callbacks;
/// - calls `0x801A1CE0`, `0x801A0E90`, [`fn_8019f0b0`], [`fn_8019f100`] and
///   [`fn_8019f180`].
///
/// # Safety
/// Hardware/emulator only; must run once before the DSP interrupt path.
///
/// # Confidence
/// medium - all loops and stores are observed; mode semantics and false
/// callbacks are inferred.
pub unsafe fn fn_801a1dd0(mode: u32) {
    write_u32(SDA_JAS_DMA_INDEX, 0);
    write_u32(SDA_JAS_DMA_INDEX_B, 0);
    write_u32(SDA_JAS_MODE, mode);
    write_u32(SDA_JAS_FRAME_STATE, 0);

    // observed: 0x20 * 9 words = 0x480 bytes.
    for block in 0..0x20 {
        for word in 0..9 {
            write_u32(JAS_MIX_BUFFER + block * 9 * 4 + word * 4, 0);
        }
    }
    platform::call2(FN_801AC470, JAS_MIX_BUFFER as u32, 0x480);

    // observed: 0x18 * 8 words = 0x300 bytes.
    for block in 0..0x18 {
        for word in 0..8 {
            write_u32(JAS_MIX_CONFIG + block * 8 * 4 + word * 4, 0);
        }
    }
    platform::call2(FN_801AC470, JAS_MIX_CONFIG as u32, 0x300);

    // observed: 0x24 * 10 words = 0x5A0 bytes.
    for block in 0..0x24 {
        for word in 0..10 {
            write_u32(JAS_RING_A + block * 10 * 4 + word * 4, 0);
        }
    }
    platform::call2(FN_801AC470, JAS_RING_A as u32, 0x5A0);

    platform::call0(FN_801A1CE0);
    fn_8019f0b0(fn_801a1ba0 as *const () as usize as u32);

    let routes = [
        JAS_RING_A as u32,
        JAS_RING_B as u32,
        JAS_RING_C as u32,
        JAS_RING_D as u32,
    ];
    write_u32(SDA_JAS_RING_READ, 0x12);
    write_u32(SDA_JAS_RING_WRITE, 0x12);
    write_u32(SDA_JAS_RING_SIZE, 0xB4);

    if mode == 1 {
        platform::call3(
            FN_801A0E90,
            JAS_MIX_CONFIG as u32,
            0x8037_CB80,
            routes.as_ptr() as u32,
        );
    } else {
        platform::call3(
            FN_801A0E90,
            JAS_MIX_CONFIG as u32,
            0x8037_CA00,
            routes.as_ptr() as u32,
        );
    }

    write_u32(SDA_JAS_DMA_STATE, 1);
    write_u32(SDA_JAS_FRAME_CB, 0);

    if mode == 1 {
        let index = read_u32(SDA_JAS_DMA_INDEX_B);
        fn_8019f100(
            (JAS_MIX_BUFFER as u32).wrapping_add(index.wrapping_mul(0x60)),
            0x180,
        );
        write_u32(SDA_JAS_DMA_INDEX_B, index.wrapping_add(1));
    } else {
        let index = read_u32(SDA_JAS_DMA_INDEX);
        fn_8019f100(
            (JAS_MIX_BUFFER as u32).wrapping_add(index.wrapping_mul(0x60)),
            0x180,
        );
    }

    fn_8019f180();
    write_u32(SDA_JAS_FRAME_END_CB, 0);
}

// ===========================================================================
// Wave 4 - JAS object pools, ring buffers, parameter accumulators, DSP task
//
// The functions below continue the JAS driver downward from the frame pump.
// They cover five jobs that the wave-3 selection left opaque:
//
// 1. the three-pool free list used to hand out JAS voice objects
//    (`0x801A0190..0x801A05B0`);
// 2. the producer/consumer ring that carries mixed 16-bit samples to the
//    caller of the driver (`0x801A1FD0..0x801A2120`);
// 3. the 20 parameter accumulators and the voice block that feeds them
//    (`0x801A2190..0x801A2E30`, plus `0x801A3130`/`0x801A3820`);
// 4. the DSP task descriptor and the callback table installed in it
//    (`0x801A1CE0`);
// 5. the game sound state machine that loads and edits the BRSAR
//    (`0x8019B660`).
//
// Every `r13 - N` access is `SDA1_BASE - N`. The pool lists live in `.bss`
// at `0x80378C10` (heads) and `0x80378C90` (tails); each array holds 32 word
// slots, indexed by the object's pool number at `+0x0C`.
// ===========================================================================

/// `r13 - 0x5180` - head of the "completed, waiting to be freed" list.
const SDA_JAS_PENDING_HEAD: usize = SDA1_BASE - 0x5180;
/// `r13 - 0x5188` - one-shot JAS initialisation latch read by [`fn_801a0050`].
const SDA_JAS_INIT_DONE: usize = SDA1_BASE - 0x5188;
/// `r13 - 0x61D0` - argument handed to `0x801AB1C0` during JAS init.
const SDA_JAS_INIT_ARG: usize = SDA1_BASE - 0x61D0;
/// `r13 - 0x50E0` - DSP-task "descriptor filled" latch; `0x801D5810` raises it.
const SDA_JAS_DSP_STARTED: usize = SDA1_BASE - 0x50E0;
/// `r13 - 0x50F0` - synchronisation object passed to `0x801B4B20`.
/// `// unknown:` the object type is an OS mutex/condition pair; only its
/// address is used here.
const SDA_JAS_DSP_LOCK: usize = SDA1_BASE - 0x50F0;
/// `r13 - 0x61C4` - 16-bit DSP task rate/table word copied to `0x8037CD10`.
const SDA_DSP_RATE_61C4: usize = SDA1_BASE - 0x61C4;
/// `r13 - 0x61C8` - 16-bit value copied to `0x8037CD24`.
const SDA_DSP_U16_61C8: usize = SDA1_BASE - 0x61C8;
/// `r13 - 0x61C6` - 16-bit value copied to `0x8037CD26`.
const SDA_DSP_U16_61C6: usize = SDA1_BASE - 0x61C6;
/// `r13 - 0x51F8` - pointer to the game sound-system object used by
/// [`fn_8019b660`]. `// inferred:` its vtable slot `+0xA4` loads a BRSAR file.
const SDA_SOUND_SYSTEM: usize = SDA1_BASE - 0x51F8;
/// `r13 - 0x51D0` - handle passed to `0x8019E080` by [`fn_8019b660`].
const SDA_SOUND_SEQ_HANDLE: usize = SDA1_BASE - 0x51D0;

/// `r13 - 0x50C8` - base of the 20 consecutive `i32` parameter accumulators.
/// Index 0 is `-0x50C8`; index 19 is `-0x507C`. They are updated by
/// [`fn_801a2450`], turned into 16-bit steps by [`fn_801a2270`], and cleared
/// by [`fn_801a23f0`].
const SDA_JAS_PARAM_ACC: usize = SDA1_BASE - 0x50C8;
/// `r13 - 0x5170` - word cleared by [`fn_801a05b0`].
const SDA_JAS_WORD_5170: usize = SDA1_BASE - 0x5170;
/// `r13 - 0x5174` - word set to 1 by [`fn_801a05b0`].
const SDA_JAS_WORD_5174: usize = SDA1_BASE - 0x5174;
/// `r13 - 0x5178` - word set to 2 by [`fn_801a05b0`].
const SDA_JAS_WORD_5178: usize = SDA1_BASE - 0x5178;

/// `0x80378C10` - 32-word head array of the JAS object free lists.
/// `// inferred:` two pools of 16 objects, but the index is not range-checked
/// in the original, so the full 32-word span is described.
const JAS_LIST_HEADS: usize = 0x8037_8C10;
/// `0x80378C90` - 32-word tail array matching [`JAS_LIST_HEADS`].
const JAS_LIST_TAILS: usize = 0x8037_8C90;
/// `0x80378D20` - first of three 0x480-byte pool backing stores cleared by
/// [`fn_801a05b0`].
const JAS_POOL_STORE_A: usize = 0x8037_8D20;
/// `0x80379F20` - second pool backing store.
const JAS_POOL_STORE_B: usize = 0x8037_9F20;
/// `0x8037B120` - third pool backing store.
const JAS_POOL_STORE_C: usize = 0x8037_B120;

/// `0x8037CDA0` - 0x78-byte block of 20 value/step pairs written by
/// [`fn_801a2270`] and flushed to main memory afterwards.
const JAS_PARAM_BLOCK: usize = 0x8037_CDA0;

/// `0x8037CD04` - DSP task field cleared by [`fn_801a1ce0`].
const DSP_TASK_04: usize = 0x8037_CD04;
/// `0x8037CD0C` - DSP task code pointer.
const DSP_TASK_0C: usize = 0x8037_CD0C;
/// `0x8037CD10` - DSP task rate word.
const DSP_TASK_10: usize = 0x8037_CD10;
/// `0x8037CD14` - DSP task field cleared by [`fn_801a1ce0`].
const DSP_TASK_14: usize = 0x8037_CD14;
/// `0x8037CD18` - DSP task work-buffer pointer (`0x8037CD60`).
const DSP_TASK_18: usize = 0x8037_CD18;
/// `0x8037CD1C` - DSP task work-buffer length (0x40).
const DSP_TASK_1C: usize = 0x8037_CD1C;
/// `0x8037CD20` - DSP task command/data length word (0xCD2).
const DSP_TASK_20: usize = 0x8037_CD20;
/// `0x8037CD24` - first 16-bit DSP task parameter.
const DSP_TASK_24: usize = 0x8037_CD24;
/// `0x8037CD26` - second 16-bit DSP task parameter.
const DSP_TASK_26: usize = 0x8037_CD26;
/// `0x8037CD28` - first DSP task callback slot (code label `0x801A1C50`).
const DSP_TASK_28: usize = 0x8037_CD28;
/// `0x8037CD2C` - second callback slot ([`fn_801a1c60`]).
const DSP_TASK_2C: usize = 0x8037_CD2C;
/// `0x8037CD30` - third callback slot (code label `0x801A1CC0`).
const DSP_TASK_30: usize = 0x8037_CD30;
/// `0x8037CD34` - fourth callback slot (data label `0x801A1CD0`).
const DSP_TASK_34: usize = 0x8037_CD34;
/// `0x8037CD60` - 0x40-byte DSP task work buffer.
const DSP_TASK_WORK: usize = 0x8037_CD60;
/// `0x8032F400` - DSP task code image pointer installed by [`fn_801a1ce0`].
const DSP_TASK_CODE: usize = 0x8032_F400;

/// `0x801A4060` - stop/disable helper used by [`fn_801a3820`].
const FN_801A4060: usize = 0x801A_4060;
/// `0x801A2E70` - voice-pool initialiser called from [`fn_801a0050`].
const FN_801A2E70: usize = 0x801A_2E70;
/// `0x801B4B20` - initialise the DSP task's condition/mutex object.
const FN_801B4B20: usize = 0x801B_4B20;
/// `0x801D5800` - query whether the DSP task is already queued.
const FN_801D5800: usize = 0x801D_5800;
/// `0x801D5740` - reset the DSP task queue.
const FN_801D5740: usize = 0x801D_5740;
/// `0x801D5810` - queue the DSP task descriptor at `0x8037CD00`.
const FN_801D5810: usize = 0x801D_5810;

/// `0x8019B4F0` - reset the game sound-system object fields.
const FN_8019B4F0: usize = 0x8019_B4F0;
/// `0x80277A90` - load a BRSAR bank group; returns 0 on success-like failure.
