///
/// The accumulator is treated as a fixed-point value in units of 0x60. The
/// whole number of units (clamped to +/-20) is written to `out_value`, the
/// accumulator keeps the remainder, and the negative of the unit count is
/// written to `out_step`. A zero unit count clears all three words.
///
/// `// observed:` the `+ (x >> 31)` / `- (q >> 31)` pair in the Ghidra output
/// is the compiler's redundant sign correction around C signed division; the
/// result equals truncation toward zero, which Rust's `/` also produces.
///
/// # Original
/// - Ghidra: `FUN_801a2190` at `0x801A2190` (108 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a2190_FUN_801a2190.c`
///
/// # Arguments
/// - `accumulator`: address of the `i32` running value.
/// - `out_value`: address of the `i32` whole value.
/// - `out_step`: address of the `i16` step word.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes all three addresses.
///
/// # Safety
/// `accumulator`/`out_value` must be writable for 4 bytes and `out_step` for
/// 2 bytes.
///
/// # Confidence
/// high - arithmetic and clamp are explicit.
pub unsafe fn fn_801a2190(accumulator: usize, out_value: usize, out_step: usize) {
    let value = read_i32(accumulator);
    let units = value / 0x60;

    if units != 0 {
        let clamped = units.clamp(-0x14, 0x14);
        write_u32(out_value, value as u32);
        write_u32(
            accumulator,
            value.wrapping_add(clamped.wrapping_mul(-0x60)) as u32,
        );
        write_u16(out_step, (-(clamped as i16)) as u16);
    } else {
        write_u32(accumulator, 0);
        write_u32(out_value, 0);
        write_u16(out_step, 0);
    }
}

/// Splits one 0x12-unit parameter accumulator into an output value and a step.
///
/// Identical to [`fn_801a2190`] with a divisor of 0x12 instead of 0x60.
///
/// # Original
/// - Ghidra: `FUN_801a2200` at `0x801A2200` (108 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a2200_FUN_801a2200.c`
///
/// # Arguments
/// - `accumulator`: address of the `i32` running value.
/// - `out_value`: address of the `i32` whole value.
/// - `out_step`: address of the `i16` step word.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes all three addresses.
///
/// # Safety
/// `accumulator`/`out_value` must be writable for 4 bytes and `out_step` for
/// 2 bytes.
///
/// # Confidence
/// high - direct twin of `0x801A2190`.
pub unsafe fn fn_801a2200(accumulator: usize, out_value: usize, out_step: usize) {
    let value = read_i32(accumulator);
    let units = value / 0x12;

    if units != 0 {
        let clamped = units.clamp(-0x14, 0x14);
        write_u32(out_value, value as u32);
        write_u32(
            accumulator,
            value.wrapping_add(clamped.wrapping_mul(-0x12)) as u32,
        );
        write_u16(out_step, (-(clamped as i16)) as u16);
    } else {
        write_u32(accumulator, 0);
        write_u32(out_value, 0);
        write_u16(out_step, 0);
    }
}

/// Publishes the 20 parameter accumulators into the DSP parameter block.
///
/// Twelve 0x60-scale accumulators and eight 0x12-scale accumulators are split
/// by [`fn_801a2190`] / [`fn_801a2200`] into the 4-byte value and 2-byte step
/// pairs that occupy `0x8037CDA0..0x8037CE17`. The block is then flushed with
/// `0x801AC470` so the DSP can read it.
///
/// `// observed:` the eight 0x12 pairs are not in address order: the first four
/// are at `0x8037CDE8/F4/00/0C`, the last four at `0x8037CDEE/FA/06/12`.
///
/// # Original
/// - Ghidra: `FUN_801a2270` at `0x801A2270` (376 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a2270_FUN_801a2270.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the parameter block and flushes 0x78 bytes of data cache.
///
/// # Safety
/// None beyond normal memory access.
///
/// # Confidence
/// high - every table index and address is explicit.
pub unsafe fn fn_801a2270() {
    // (accumulator, output value, output step), divisor 0x60.
    // The destination addresses are the value/step words inside
    // JAS_PARAM_BLOCK (0x8037CDA0..0x8037CE17).
    const PAIRS_60: [(usize, usize, usize); 12] = [
        (SDA_JAS_PARAM_ACC + 19 * 4, 0x8037_CDA0, 0x8037_CDA4),
        (SDA_JAS_PARAM_ACC + 18 * 4, 0x8037_CDA6, 0x8037_CDAA),
        (SDA_JAS_PARAM_ACC + 17 * 4, 0x8037_CDAC, 0x8037_CDB0),
        (SDA_JAS_PARAM_ACC + 16 * 4, 0x8037_CDB2, 0x8037_CDB6),
        (SDA_JAS_PARAM_ACC + 15 * 4, 0x8037_CDB8, 0x8037_CDBC),
        (SDA_JAS_PARAM_ACC + 14 * 4, 0x8037_CDBE, 0x8037_CDC2),
        (SDA_JAS_PARAM_ACC + 13 * 4, 0x8037_CDC4, 0x8037_CDC8),
        (SDA_JAS_PARAM_ACC + 12 * 4, 0x8037_CDCA, 0x8037_CDCE),
        (SDA_JAS_PARAM_ACC + 11 * 4, 0x8037_CDD0, 0x8037_CDD4),
        (SDA_JAS_PARAM_ACC + 10 * 4, 0x8037_CDD6, 0x8037_CDDA),
        (SDA_JAS_PARAM_ACC + 9 * 4, 0x8037_CDDC, 0x8037_CDE0),
        (SDA_JAS_PARAM_ACC + 8 * 4, 0x8037_CDE2, 0x8037_CDE6),
    ];
    // (accumulator, output value, output step), divisor 0x12.
    const PAIRS_18: [(usize, usize, usize); 8] = [
        (SDA_JAS_PARAM_ACC + 7 * 4, 0x8037_CDE8, 0x8037_CDEC),
        (SDA_JAS_PARAM_ACC + 6 * 4, 0x8037_CDF4, 0x8037_CDF8),
        (SDA_JAS_PARAM_ACC + 5 * 4, 0x8037_CE00, 0x8037_CE04),
        (SDA_JAS_PARAM_ACC + 4 * 4, 0x8037_CE0C, 0x8037_CE10),
        (SDA_JAS_PARAM_ACC + 3 * 4, 0x8037_CDEE, 0x8037_CDF2),
        (SDA_JAS_PARAM_ACC + 2 * 4, 0x8037_CDFA, 0x8037_CDFE),
        (SDA_JAS_PARAM_ACC + 1 * 4, 0x8037_CE06, 0x8037_CE0A),
        (SDA_JAS_PARAM_ACC + 0 * 4, 0x8037_CE12, 0x8037_CE16),
    ];

    for &(accumulator, out_value, out_step) in PAIRS_60.iter() {
        fn_801a2190(accumulator, out_value, out_step);
    }
    for &(accumulator, out_value, out_step) in PAIRS_18.iter() {
        fn_801a2200(accumulator, out_value, out_step);
    }

    platform::call2(FN_801AC470, JAS_PARAM_BLOCK as u32, 0x78);
}

/// Clears the 20 parameter accumulators.
///
/// The words `r13 - 0x50C8 .. -0x507C` are written in ascending address
/// order, matching the original store sequence.
///
/// # Original
/// - Ghidra: `FUN_801a23f0` at `0x801A23F0` (88 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a23f0_FUN_801a23f0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes 20 zero words.
///
/// # Safety
/// None beyond normal writable memory.
///
/// # Confidence
/// high - 20 explicit stores are observed.
pub unsafe fn fn_801a23f0() {
    for index in 0..20 {
        write_u32(SDA_JAS_PARAM_ACC + index * 4, 0);
    }
}

/// Adds a voice's output parameters into the 20 running accumulators.
