/// Sets one 16-bit voice parameter and marks it dirty.
///
/// With interrupts disabled, compares the halfword at `+0x38` with the new
/// value. A change stores the value, sets bit 2 of the `+0x1C` flags, and
/// (when the new value is zero) writes 1 to `+0x20`. An unchanged value only
/// restores interrupts.
///
/// # Original
/// - Ghidra: `FUN_801a3130` at `0x801A3130` (112 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a3130_FUN_801a3130.c`
///
/// # Arguments
/// - `voice`: voice block address.
/// - `value`: new 16-bit parameter.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x38`, may set `+0x1C` bit 2 and write `+0x20`.
///
/// # Safety
/// `voice` must be a writable voice block.
///
/// # Confidence
/// high - comparison and stores are explicit; the interrupt token is
/// reconstructed from the ABI.
pub unsafe fn fn_801a3130(voice: u32, value: u32) {
    let state = call0_u32(FN_801B1140);
    let p = voice as usize;
    if read_u16(p + 0x38) as u32 == value {
        platform::call1(FN_801B1180, state);
    } else {
        write_u16(p + 0x38, value as u16);
        write_u32(p + 0x1C, read_u32(p + 0x1C) | 4);
        if value == 0 {
            write_u32(p + 0x20, 1);
        }
        platform::call1(FN_801B1180, state);
    }
}

/// Stops one AX voice and marks its state as stopped.
///
/// With interrupts disabled, sets bit 0 of the voice's `+0x10C` flags, calls
/// the stop helper `0x801A4060`, and restores interrupts.
///
/// # Original
/// - Ghidra: `FUN_801a3820` at `0x801A3820` (84 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a3820_FUN_801a3820.c`
///
/// # Arguments
/// - `voice`: voice block address.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x10C`, calls `0x801A4060`, disables/restores interrupts.
///
/// # Safety
/// `voice` must be a live AX voice block.
///
/// # Confidence
/// high - flag write and call are explicit; the helper role is inferred from
/// its position beside the start/slow-start pair.
pub unsafe fn fn_801a3820(voice: u32) {
    let state = call0_u32(FN_801B1140);
    let p = voice as usize;
    write_u32(p + 0x10C, read_u32(p + 0x10C) | 1);
    platform::call1(FN_801A4060, voice);
    platform::call1(FN_801B1180, state);
}

/// Game sound-system state transition and BRSAR load hook.
///
/// Resets six fields of the sound object, then handles three cases:
///
/// * state 0 - run the reset helper, load `Sound/wii/mj2d_sound.brsar`
///   through vtable slot `+0xA4`, then load the bank group at object `+0x5BC`;
/// * state 1 - move to state 1 without touching the archive;
/// * any other state - record the old state, set the new one, iterate the
///   archive's group table (skipping groups 0, 0x10..0x12 and 0x15), set
///   group `0x32`, apply the state-specific fades, and dispatch the new state
///   through `0x8019E080`.
///
/// # Original
/// - Ghidra: `FUN_8019b660` at `0x8019B660` (544 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8019b660_FUN_8019b660.c`
/// - `// observed:` the string is `s__Sound_wii_mj2d_sound_brsar_8032e12c`
///   at `0x8032E12C`; the archive pointer is object `+0x5BC`.
///
/// # Arguments
/// - `sound`: sound-system object address.
/// - `next_state`: requested state; 0 loads, 1 arms, others transition.
///
/// # Returns
/// 1 on success, 0 when the BRSAR or bank-group load reports failure (state 0
/// only), or the result of `0x8019E080`.
///
/// # Side effects
/// Writes the object's state fields, loads a BRSAR, walks and edits its group
/// table, and may schedule fades.
///
/// # Safety
/// `sound` must be a live sound-system object; the global at
/// `r13 - 0x51F8` must hold a matching object with vtable slot `+0xA4`.
///
/// # Confidence
/// medium - control flow and offsets are observed; the vtable call and the
/// exact BRSAR return conventions are inferred from their shapes.
pub unsafe fn fn_8019b660(sound: u32, next_state: i32) -> u32 {
    let p = sound as usize;

    write_u8(p + 0x30, 0);
    write_u8(p + 0x3D, 1);
    write_u8(p + 0x3F, 0);
    write_u32(p + 0x40, 0);
    write_u8(p + 0x44, 0);
    write_u32(p + 0x34, 0);

    if next_state == 0 {
        // inferred: the reset helper takes the same object, although Ghidra
        // drops its argument at this call site.
        platform::call1(FN_8019B4F0, sound);

        let system = read_u32(SDA_SOUND_SYSTEM) as usize;
        let load = read_u32(system + 0xA4) as usize;
        let loaded = platform::call4(
            load,
            system as u32,
            STR_MJ2D_SOUND_BRSAR as u32,
            0,
            1,
        );
        if loaded == 0 {
            return 0;
        }

        let archive = read_u32(system + 0x5BC);
        if platform::call1(FN_80277A90, archive) == 0 {
            return 0;
        }
        return 1;
    }

    if next_state == 1 {
        write_u32(p + 0x10, read_u32(p + 0x14));
        write_u32(p + 0x14, 1);
        return 1;
    }

    if next_state == read_i32(p + 0x14) {
        if next_state == 3 {
            write_u8(p + 0x3D, 0);
        }
        return 1;
    }

    write_u32(p + 0x10, read_u32(p + 0x14));
    write_u32(p + 0x14, next_state as u32);
    write_u16(p + 0x1C, 0);

    let system = read_u32(SDA_SOUND_SYSTEM) as usize;
    let mut index = 0u32;
    loop {
        let archive_now = read_u32(system + 0x5BC) as usize;
        if read_u32(archive_now + 0x3C) <= index {
            break;
        }
        if (index < 0x10 || 0x12 < index) && index != 0 && index != 0x15 {
            let group = platform::call2(FN_80278780, archive_now as u32, index);
            platform::call2(FN_8027A7D0, group, 0x32);
        }
        index += 1;
    }

    if platform::call2(FN_80196600, system as u32, 0xAF) != 0 {
        platform::call2(FN_80195CB0, system as u32, 0x32);
    }

    if next_state == 6 {
        if read_i32(p + 0x10) == 5 {
            platform::call3(FN_8019BAF0, sound, 0xF0, 0xFFFF_FFFF);
        } else {
            write_u32(p + 0x14, 7);
            platform::call3(FN_8019BAF0, sound, 300, 0x3C);
        }
    }

    if next_state == 5 {
        if read_u32(p + 0x10).wrapping_sub(6) < 2 {
            platform::call3(FN_8019BAF0, sound, 0x78, 0xFFFF_FFFF);
        }
    } else if next_state == 0x11 {
        platform::call2(FN_80195F10, system as u32, 0x32);
    }

    if read_i32(p + 0x14) == 0x11 {
        write_u8(p + 0x38, 0);
        return 1;
    }

    platform::call3(
        FN_8019E080,
        read_u32(SDA_SOUND_SEQ_HANDLE),
        next_state as u32,
        0,
    )
}

// ===========================================================================
// Wave 5 - JAS voice buffers and JAI timer queue
//
// The functions below continue the JAS/JAI driver below the wave-4 parameter
// block. They cover four jobs:
//
// 1. per-voice parameter and envelope setup (`0x801A31A0..0x801A34F0`);
// 2. the per-voice sample-buffer tables: allocate, clear and free
//    (`0x801A3F30..0x801A72F0`);
// 3. the 2-, 3- and 4-buffer note start/retry/stop state machines;
// 4. the JAI sequence timer list and its block free-list coalescer
//    (`0x801AB640..0x801ABB40`).
//
// Wave-5 `r13` globals are `SDA1_BASE - N`. The float limits used by the note
// setup paths are `r2`-relative, i.e. `SDA2_BASE - N`, and are unnamed in the
// image; their roles are inferred from the comparisons around them.
//
// The CodeWarrior register-save prologues `0x802DCD68`/`0x802DCD6C`/
// `0x802DCD70`/`0x802DCD74` are not functions: they preserve registers and
// leave `r3` untouched. Ghidra prints their return value as the object pointer,
// so the Rust signatures below take that pointer explicitly (`voice`/`ctx`).
// The matching restore thunks are omitted.
// ===========================================================================

/// `r13 - 0x5058` - non-zero while the voice-slot ring is enabled.
const SDA_VOICE_RING_ENABLED: usize = SDA1_BASE - 0x5058;
/// `r13 - 0x5054` - current voice-slot cursor, advanced modulo the count.
const SDA_VOICE_RING_CURSOR: usize = SDA1_BASE - 0x5054;
/// `r13 - 0x5050` - number of 0x38-byte voice slots in the ring.
const SDA_VOICE_RING_COUNT: usize = SDA1_BASE - 0x5050;
/// `r13 - 0x504C` - base of the 0x38-byte voice-slot ring.
const SDA_VOICE_RING_TABLE: usize = SDA1_BASE - 0x504C;

/// `r13 - 0x61C0` - heap-allocator hook called with a byte count.
/// `// unknown:` the concrete allocator is not named in the image.
const SDA_JAS_ALLOC_HOOK: usize = SDA1_BASE - 0x61C0;
/// `r13 - 0x61BC` - matching free hook called with a buffer pointer.
/// `// unknown:` the concrete free function is not named in the image.
const SDA_JAS_FREE_HOOK: usize = SDA1_BASE - 0x61BC;

/// `r13 - 0x5000` - head of the sorted JAI timer list.
const SDA_JAI_TIMER_HEAD: usize = SDA1_BASE - 0x5000;
/// `r13 - 0x4FFC` - tail of the sorted JAI timer list.
const SDA_JAI_TIMER_TAIL: usize = SDA1_BASE - 0x4FFC;

/// `r2 - 0x5150` - word copied to voice `+0x130` and `+0x144`.
/// `// unknown:` the producer of this value is outside the selected band.
const SDA2_VOICE_ARG_5150: usize = SDA2_BASE - 0x5150;
/// `r2 - 0x514C` - word copied to voice `+0x134`.
/// `// unknown:` the producer of this value is outside the selected band.
const SDA2_VOICE_ARG_514C: usize = SDA2_BASE - 0x514C;

/// `r2 - 0x5144` - lower pitch/time limit used by [`fn_801a34f0`].
const SDA2_VOICE_START_LIMIT: usize = SDA2_BASE - 0x5144;
/// `r2 - 0x5148` - scale applied to the voice's +0x114 value.
const SDA2_VOICE_START_SCALE: usize = SDA2_BASE - 0x5148;

/// `r2 - 0x50C4` - lower pitch limit used by the 3-buffer note path.
const SDA2_VOICE_PITCH_LOW: usize = SDA2_BASE - 0x50C4;
/// `r2 - 0x50C8` - sample-count scale used by the 3-buffer note path.
const SDA2_VOICE_PITCH_SCALE: usize = SDA2_BASE - 0x50C8;
/// `r2 - 0x50C0` - upper pitch limit used by the 3-buffer note path.
