/// `r2 - 0x50A4` - envelope multiplier used by [`fn_801a67a0`].
const SDA2_VOICE_STREAM_GAIN: usize = SDA2_BASE - 0x50A4;
/// `r2 - 0x50A0` - envelope ramp cap used by [`fn_801a67a0`].
const SDA2_VOICE_STREAM_CAP: usize = SDA2_BASE - 0x50A0;

