const FN_801A4180: usize = 0x801A_4180;
/// `0x801A69C0` - start the 2-buffer voice path.
const FN_801A69C0: usize = 0x801A_69C0;
/// `0x801A73E0` - build the 2-buffer voice mixer state.
const FN_801A73E0: usize = 0x801A_73E0;
