const FN_801A9B80: usize = 0x801A_9B80;
/// `0x801CFA30` - test whether a JAI timer object is still alive.
const FN_801CFA30: usize = 0x801C_FA30;

/// `0x8033145C` - word copied to voice `+0x1C` by [`fn_801a34f0`].
const DAT_8033145C: usize = 0x8033_145C;
/// `0x80331580` - word copied to voice `+0x80`.
const DAT_80331580: usize = 0x8033_1580;
/// `0x80331584` - word copied to voice `+0x84`.
const DAT_80331584: usize = 0x8033_1584;
/// `0x80331588` - word copied to voice `+0x88`.
const DAT_80331588: usize = 0x8033_1588;
/// `0x8033158C` - word copied to voice `+0xC0`.
const DAT_8033158C: usize = 0x8033_158C;
/// `0x80331590` - word copied to voice `+0xC4`.
const DAT_80331590: usize = 0x8033_1590;
/// `0x80331594` - word copied to voice `+0xEC`.
const DAT_80331594: usize = 0x8033_1594;
/// `0x80331598` - word copied to voice `+0xF0`.
const DAT_80331598: usize = 0x8033_1598;
/// `0x8033159C` - word copied to voice `+0xF4`.
const DAT_8033159C: usize = 0x8033_159C;

/// Truncating `f32` to `i32`, the role of the compiler helper `0x802DCC4C`.
///
/// # Original
/// Host-side helper; models the CodeWarrior float-to-integer conversion called
/// from [`fn_801a34f0`], [`fn_801a55f0`], [`fn_801a5e90`], [`fn_801a60c0`] and
/// [`fn_801a67a0`].
///
/// # Safety
/// Plain arithmetic; no pointer access.
///
/// # Confidence
/// medium - Rust truncates toward zero like the observed conversion; NaN and
/// out-of-range saturation are not bit-exact with the PowerPC helper.
#[inline]
fn wave5_f32_to_i32(value: f32) -> i32 {
    value as i32
}

/// Calls the JAS heap allocator hook with a byte count.
///
/// # Original
/// Host-side helper; models `(**(code **)(r13 - 0x61C0))(bytes)`.
///
/// # Safety
/// The SDA slot must hold a valid function pointer.
///
/// # Confidence
/// high - the call shape is observed; the concrete allocator is unknown.
#[inline]
unsafe fn wave5_alloc(bytes: u32) -> u32 {
    let alloc = read_u32(SDA_JAS_ALLOC_HOOK) as usize;
    platform::call1(alloc, bytes)
}

/// Calls the JAS heap free hook with one buffer pointer.
///
/// # Original
/// Host-side helper; models `(**(code **)(r13 - 0x61BC))(ptr)`.
///
/// # Safety
/// The SDA slot must hold a valid function pointer and `ptr` must come from
/// the matching allocator.
///
/// # Confidence
/// high - the call shape is observed; the concrete free function is unknown.
#[inline]
unsafe fn wave5_free(ptr: u32) {
    let free = read_u32(SDA_JAS_FREE_HOOK) as usize;
    platform::call1(free, ptr);
}

/// Frees and clears the three sample buffers at voice `+0x00/+0x04/+0x08`.
///
/// # Original
/// Host-side helper for the repeated cleanup in [`fn_801a55f0`],
/// [`fn_801a58c0`] and [`fn_801a5b60`].
///
/// # Safety
/// `voice` must point at a voice block whose three buffer fields are either 0
/// or pointers returned by [`wave5_alloc`].
///
/// # Confidence
/// high - order and null checks match the three observed cleanup blocks.
#[inline]
unsafe fn wave5_free_three(voice: u32) {
    let p = voice as usize;
    for offset in [0usize, 4, 8] {
        let buffer = read_u32(p + offset);
        if buffer != 0 {
            wave5_free(buffer);
            write_u32(p + offset, 0);
        }
    }
}

/// Frees and clears the four sample buffers at voice `+0x00..+0x0C`.
///
/// # Original
/// Host-side helper for the repeated cleanup in [`fn_801a60c0`],
/// [`fn_801a62f0`], [`fn_801a6420`] and [`fn_801a64f0`].
///
/// # Safety
/// `voice` must point at a voice block whose four buffer fields are either 0
/// or pointers returned by [`wave5_alloc`].
///
/// # Confidence
/// high - order and null checks match the four observed cleanup loops.
#[inline]
unsafe fn wave5_free_four(voice: u32) {
    let p = voice as usize;
    for offset in [0usize, 4, 8, 0x0C] {
        let buffer = read_u32(p + offset);
        if buffer != 0 {
            wave5_free(buffer);
            write_u32(p + offset, 0);
        }
    }
}

/// Clamps `expiry - now` to the 0..0x7FFFFFFF range used by
/// [`crate::runtime::os::cancel_alarm`].
///
/// # Original
/// Host-side helper for the 64-bit compare and `0x801A9B80(0 | remaining |
/// 0x7FFFFFFF)` sequence in `FUN_801ab640`.
///
/// # Arguments
/// - `expiry_hi` / `expiry_lo`: the timer's big-endian 64-bit deadline.
/// - `now`: the current 64-bit tick count from `0x801B5FB0`.
///
/// # Returns
/// 0 when the deadline has passed, the low 32 bits when the remaining time
/// fits in a positive signed word, otherwise `0x7FFFFFFF`.
///
/// # Safety
/// Plain arithmetic.
///
/// # Confidence
/// medium - the clamp is reproduced from the observed 64-bit subtract and
/// signed compare; the unit of the tick count is not named.
#[inline]
fn wave5_timeout(expiry_hi: u32, expiry_lo: u32, now: u64) -> u32 {
    let now_lo = now as u32;
    let now_hi = (now >> 32) as u32;
    let low = expiry_lo.wrapping_sub(now_lo);
    let borrow = (expiry_lo < now_lo) as u32;
    let high = expiry_hi.wrapping_sub(now_hi.wrapping_add(borrow));
    let signed_high = high ^ 0x8000_0000;

    if signed_high < 0x8000_0000 {
        0
    } else if signed_high < ((low < 0x8000_0000) as u32) + 0x8000_0000 {
        low
    } else {
        0x7FFF_FFFF
    }
}

/// Stores a voice's 4-word parameter block and resets two waveform-dependent
/// accumulator groups.
///
/// The first four words of `param` are copied to voice `+0x96/+0x9A/+0x9E/+0xA2`.
/// When the 16-bit tag at `param + 2` is 10 or 0x19, the ten words at
/// `+0xA6..+0xCA` are cleared and `+0xC6` receives `0x08000000` or `0x01000000`
/// respectively. Finally the flag word at `+0x1C` is rewritten with
/// `(... & 0xFFFF87FF) | 0x8400`.
///
/// # Original
/// - Ghidra: `FUN_801a31a0` at `0x801A31A0` (232 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a31a0_FUN_801a31a0.c`
///
/// # Arguments
/// - `voice`: voice object whose parameter words are updated.
/// - `param`: four-word source block; only its low halfword at `+2` is
///   interpreted as a tag.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the voice parameter/accumulator words and brackets the block with
/// the interrupt disable/restore pair `0x801B1140`/`0x801B1180`.
///
/// # Safety
/// Both pointers must be valid; the offsets are unaligned 32-bit accesses and
/// are written byte-wise by [`crate::platform`].
///
/// # Confidence
/// high - every store and both tag cases are explicit; only the restore token
/// is reconstructed from the ABI.
pub unsafe fn fn_801a31a0(voice: u32, param: u32) {
    let v = voice as usize;
    let p = param as usize;
    let state = call0_u32(FN_801B1140);

    write_u32(v + 0x96, read_u32(p));
    write_u32(v + 0x9A, read_u32(p + 4));
    write_u32(v + 0x9E, read_u32(p + 8));
    write_u32(v + 0xA2, read_u32(p + 0x0C));

    let tag = read_u16(p + 2);
    if tag == 10 || tag == 0x19 {
        for offset in [0xA6usize, 0xAA, 0xAE, 0xB2, 0xB6, 0xBA, 0xBE, 0xC2] {
            write_u32(v + offset, 0);
        }
        write_u32(v + 0xC6, if tag == 10 { 0x0800_0000 } else { 0x0100_0000 });
        write_u32(v + 0xCA, 0);
    }

    // observed: 0xFFFF87FF clears the waveform/format field; 0x8400 sets the
    // two replacement bits.
    write_u32(v + 0x1C, (read_u32(v + 0x1C) & 0xFFFF_87FF) | 0x8400);
    platform::call1(FN_801B1180, state);
}

/// Hands out the next 0x38-byte voice slot from a round-robin ring.
///
/// Returns 0 when the ring is disabled (`r13 - 0x5058 == 0`). Otherwise it
/// returns `table + cursor * 0x38`, then stores `(cursor + 1) % count` back to
/// the cursor at `r13 - 0x5054`. The slot is handed out before the cursor
/// advances, so the first call returns slot 0.
///
/// # Original
/// - Ghidra: `FUN_801a3370` at `0x801A3370` (64 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a3370_FUN_801a3370.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Address of the current voice slot, or 0 when the ring is disabled.
///
/// # Side effects
/// Advances the ring cursor at `r13 - 0x5054`.
///
/// # Safety
/// The count at `r13 - 0x5050` must be non-zero while the ring is enabled and
/// the table base at `r13 - 0x504C` must address `count * 0x38` bytes.
///
/// # Confidence
/// high - the modulo, stride and return address are explicit.
pub unsafe fn fn_801a3370() -> u32 {
    if read_u32(SDA_VOICE_RING_ENABLED) == 0 {
        return 0;
    }

    let cursor = read_u32(SDA_VOICE_RING_CURSOR);
    let count = read_u32(SDA_VOICE_RING_COUNT);
    let next = cursor.wrapping_add(1) % count;
    write_u32(SDA_VOICE_RING_CURSOR, next);
    read_u32(SDA_VOICE_RING_TABLE).wrapping_add(cursor.wrapping_mul(0x38))
}

/// Initialises the envelope state of a voice and starts it.
///
/// The function copies the voice's sustain/decay words into the envelope
/// fields, stores state 5 at `+0x110`, inserts two global voice parameters
/// (`r2 - 0x5150` into `+0x130`/`+0x144`, `r2 - 0x514C` into `+0x134`), clears
/// the three rate words, and tail-calls the voice start path
/// [`FN_801A34F0`].
///
/// # Original
/// - Ghidra: `FUN_801a33b0` at `0x801A33B0` (100 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a33b0_FUN_801a33b0.c`
///
/// # Arguments
/// - `voice`: voice object to initialise.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes fourteen voice words and calls `0x801A34F0`, which may allocate
/// sample buffers.
///
/// # Safety
/// `voice` must be a live voice block and the SDA callback-argument words must
/// hold the values expected by the current JAS session.
///
/// # Confidence
/// high - all offsets and the tail call are explicit.
pub unsafe fn fn_801a33b0(voice: u32) {
    let v = voice as usize;
    let arg_b = read_u32(SDA2_VOICE_ARG_5150);
    let arg_a = read_u32(SDA2_VOICE_ARG_514C);

    write_u32(v + 0x110, 5);
    write_u32(v + 0x114, read_u32(v + 0x158));
    write_u32(v + 0x118, read_u32(v + 0x158));
    write_u32(v + 0x11C, 0);
    write_u32(v + 0x120, read_u32(v + 0x150));
    write_u32(v + 0x124, read_u32(v + 0x148));
    write_u32(v + 0x128, read_u32(v + 0x154));
    write_u32(v + 0x12C, read_u32(v + 0x15C));
    write_u32(v + 0x130, arg_b);
    write_u32(v + 0x134, arg_a);
    write_u32(v + 0x138, 0);
    write_u32(v + 0x13C, 0);
    write_u32(v + 0x140, read_u32(v + 0x14C));
    write_u32(v + 0x144, arg_b);

    platform::call1(FN_801A34F0, voice);
}

/// Starts one voice after filling its pitch and envelope fields.
///
/// The function takes the interrupt lock, sets `+0x10C = 1`, and rejects the
/// note when the global lower limit at `r2 - 0x5144` exceeds the voice's
/// `+0x114` value. On the accept path it stores a constant at `+0x1C`, converts
/// `r2 - 0x5148 * +0x114` into the sample count at `+0x40`, copies eight
/// mix-constant words into `+0x80..+0xF4`, and calls the buffer allocator
/// `0x801A3DB0`. A failed allocation or a failed `0x801A4180` configuration
/// sets the stop bit, frees the buffers through `0x801A4060`, and returns 0;
/// success clears bit 0 and returns 1.
///
/// # Original
/// - Ghidra: `FUN_801a34f0` at `0x801A34F0` (412 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a34f0_FUN_801a34f0.c`
///
/// # Arguments
/// - `voice`: voice object to start.
///
/// # Returns
/// 1 on success, 0 when the pitch limit rejects the note or a buffer step
/// fails.
///
/// # Side effects
/// Writes voice fields, allocates/frees sample buffers, and brackets the work
/// with `0x801B1140`/`0x801B1180`.
///
/// # Safety
/// `voice` must be a live voice block; the allocator hooks installed at
/// `r13 - 0x61C0`/`r13 - 0x61BC` must be valid.
///
/// # Confidence
/// medium - the flow is explicit; the unnamed float limits, the constant words
/// and the float-to-int conversion helper are inferred.
pub unsafe fn fn_801a34f0(voice: u32) -> u32 {
    let v = voice as usize;
    let state = call0_u32(FN_801B1140);
    let limit = read_f32(SDA2_VOICE_START_LIMIT);
    write_u32(v + 0x10C, 1);

    if limit <= read_f32(v + 0x114) {
        let scale = read_f32(SDA2_VOICE_START_SCALE);
        write_u32(v + 0x1C, read_u32(DAT_8033145C));
        let samples = wave5_f32_to_i32(scale * read_f32(v + 0x114));
        write_u32(v + 0x40, samples as u32);

        write_u32(v + 0x80, read_u32(DAT_80331580));
        write_u32(v + 0x84, read_u32(DAT_80331584));
        write_u32(v + 0x88, read_u32(DAT_80331588));
        write_u32(v + 0xC0, read_u32(DAT_8033158C));
        write_u32(v + 0xC4, read_u32(DAT_80331590));
        write_u32(v + 0xEC, read_u32(DAT_80331594));
        write_u32(v + 0xF0, read_u32(DAT_80331598));
        write_u32(v + 0xF4, read_u32(DAT_8033159C));

        if platform::call1(FN_801A3DB0, voice) == 0 {
            let inner = call0_u32(FN_801B1140);
            write_u32(v + 0x10C, read_u32(v + 0x10C) | 1);
            platform::call1(FN_801A4060, voice);
            platform::call1(FN_801B1180, inner);
            platform::call1(FN_801B1180, state);
            return 0;
        }

        fn_801a3f30(voice);
        if platform::call1(FN_801A4180, voice) == 0 {
            let inner = call0_u32(FN_801B1140);
            write_u32(v + 0x10C, read_u32(v + 0x10C) | 1);
            platform::call1(FN_801A4060, voice);
            platform::call1(FN_801B1180, inner);
            platform::call1(FN_801B1180, state);
            return 0;
        }

        write_u32(v + 0x10C, read_u32(v + 0x10C) & 0xFFFF_FFFE);
        platform::call1(FN_801B1180, state);
        return 1;
    }

    let inner = call0_u32(FN_801B1140);
    write_u32(v + 0x10C, read_u32(v + 0x10C) | 1);
    platform::call1(FN_801A4060, voice);
    platform::call1(FN_801B1180, inner);
    platform::call1(FN_801B1180, state);
    0
}

/// Clears every sample buffer referenced by a voice buffer table.
///
/// The table has three voice slots. For each slot it clears the main
/// buffer (`+0x00`), the optional second buffer (`+0x2C`), three per-tap
/// buffers at `+0x44 + slot*0x0C`, two history buffers at `+0x98 + slot*0x08`,
/// and one extra buffer at `+0xC8 + slot*0x04`. Each clear uses the
/// memset-shaped helper `0x800046B4` with the length word from the table.
///
/// # Original
/// - Ghidra: `FUN_801a3f30` at `0x801A3F30` (292 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a3f30_FUN_801a3f30.c`
///
/// # Arguments
/// - `ctx`: buffer-table base. Ghidra loses the argument behind the
///   `0x802DCD68` register-save thunk; it is the incoming `r3`.
///
/// # Returns
/// 1 after all three slots are cleared.
///
/// # Side effects
/// Zeroes every non-null sample buffer; does not clear the pointers.
///
/// # Safety
/// `ctx` must be a live JAS voice buffer table and each pointer must cover the
/// table's corresponding length.
///
/// # Confidence
/// high - all offsets, lengths and loop bounds are explicit.
pub unsafe fn fn_801a3f30(ctx: u32) -> u32 {
    let p = ctx as usize;

    for slot in 0..3usize {
        let main = read_u32(p + slot * 4);
        if main != 0 {
            platform::call3(FN_800046B4, main, 0, read_u32(p + 0x1C) << 2);
        }

        let second = read_u32(p + slot * 4 + 0x2C);
        if second != 0 {
            platform::call3(FN_800046B4, second, 0, read_u32(p + 0x40) << 2);
        }

        for tap in 0..3usize {
            let buffer = read_u32(p + slot * 12 + 0x44 + tap * 4);
            if buffer != 0 {
                platform::call3(
                    FN_800046B4,
                    buffer,
                    0,
                    read_u32(p + 0x80 + tap * 4) << 2,
                );
            }
        }

        for history in 0..2usize {
            let buffer = read_u32(p + slot * 8 + 0x98 + history * 4);
            if buffer != 0 {
                platform::call3(
                    FN_800046B4,
                    buffer,
                    0,
                    read_u32(p + 0xC0 + history * 4) << 2,
                );
            }
        }

        let extra = read_u32(p + slot * 4 + 0xC8);
        if extra != 0 {
            platform::call3(FN_800046B4, extra, 0, read_u32(p + slot * 4 + 0xEC) << 2);
        }
    }

    1
}

/// Frees every sample buffer referenced by a voice buffer table.
///
/// The traversal is the same as [`fn_801a3f30`], but each non-null pointer is
/// passed to the JAS free hook and then zeroed. The free hook calls in the
/// Ghidra output have no visible argument; the pointer of the surrounding null
/// test is used here (`// inferred:` from the allocator/free pairing).
///
/// # Original
/// - Ghidra: `FUN_801a4060` at `0x801A4060` (276 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a4060_FUN_801a4060.c`
///
/// # Arguments
/// - `ctx`: buffer-table base. Ghidra loses the argument behind the
///   `0x802DCD6C` register-save thunk; it is the incoming `r3`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Calls the free hook once per non-null buffer and zeroes its pointer.
///
/// # Safety
/// Every pointer in the table must have come from the matching JAS allocator.
///
/// # Confidence
/// high - offsets and loop bounds are explicit; only the dropped free-hook
/// arguments are reconstructed.
pub unsafe fn fn_801a4060(ctx: u32) {
    let p = ctx as usize;

    for slot in 0..3usize {
        let main = read_u32(p + slot * 4);
        if main != 0 {
            wave5_free(main);
            write_u32(p + slot * 4, 0);
        }

        let second = read_u32(p + slot * 4 + 0x2C);
        if second != 0 {
            wave5_free(second);
            write_u32(p + slot * 4 + 0x2C, 0);
        }

        for tap in 0..3usize {
            let offset = p + slot * 12 + 0x44 + tap * 4;
            let buffer = read_u32(offset);
            if buffer != 0 {
                wave5_free(buffer);
                write_u32(offset, 0);
            }
        }

        for history in 0..2usize {
            let offset = p + slot * 8 + 0x98 + history * 4;
            let buffer = read_u32(offset);
            if buffer != 0 {
                wave5_free(buffer);
                write_u32(offset, 0);
            }
        }

        let offset = p + slot * 4 + 0xC8;
        let extra = read_u32(offset);
        if extra != 0 {
            wave5_free(extra);
            write_u32(offset, 0);
        }
    }
}

/// Allocates the three buffers of the 3-buffer sample set and starts it.
///
/// The function rejects the note when the global pitch limit at
/// `r2 - 0x50C4` is not below the voice's `+0x38` value. It then computes the
/// buffer length `r2 - 0x50C8 * +0x38` into `+0x14` (at least 1), allocates
/// three buffers of `len * 4` bytes into `+0x00/+0x04/+0x08`, and calls the
/// configuration step [`fn_801a5e90`]. Any allocation or configuration failure
/// sets bit 0, frees the three buffers, and returns 0; success sets
/// `(flags & ~1) | 2` and returns 1.
///
/// # Original
/// - Ghidra: `FUN_801a55f0` at `0x801A55F0` (720 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a55f0_FUN_801a55f0.c`
///
/// # Arguments
/// - `ctx`: 3-buffer voice block. Ghidra prints it as `int *param_1`.
///
/// # Returns
/// 1 on success, 0 when rejected or when a buffer step fails.
