        write_u32(v + 0x6C, read_u32(DAT_80331870));
        write_u32(v + 0x70, read_u32(DAT_80331874));
        write_u32(v + 0xAC, read_u32(DAT_80331878));
        write_u32(v + 0xB0, read_u32(DAT_8033187C));

