const SDA_VOICE_PARAM_TABLE: usize = SDA1_BASE - 0x5078;
/// `r13 - 0x506C` - number of 0x140-byte voice parameter blocks.
const SDA_VOICE_COUNT: usize = SDA1_BASE - 0x506C;
/// `r13 - 0x5074` - second per-voice table (0x40 bytes per voice).
const SDA_VOICE_AUX_TABLE: usize = SDA1_BASE - 0x5074;
