/// `0x8032E398` - voice-priority cost table indexed by the four fields of a
/// note's `+0x34` word.
const DAT_8032E398: usize = 0x8032_E398;
/// `0x8032E418` - eight-entry cost table indexed by the `+0x100` bitfield.
const DAT_8032E418: usize = 0x8032_E418;

/// Frees the three buffers of a 3-voice sequence set under a fresh lock.
///
/// This is the shared failure tail of [`fn_801a8410`] and [`fn_801a8670`]:
/// take the interrupt lock again, set the stop bit at `+0x7C`, free and zero
/// `+0x00/+0x04/+0x08`, then release both the nested and the caller's lock.
///
/// # Original
/// Host-side helper for the repeated cleanup in `FUN_801a8410`/`FUN_801a8670`.
///
/// # Safety
/// `v` must be a live 3-voice sequence block and `outer` a token from
/// `0x801B1140`.
unsafe fn sequence3_release(v: usize, outer: u32) -> u32 {
    let inner = call0_u32(FN_801B1140);
    write_u32(v + 0x7C, read_u32(v + 0x7C) | 1);
    for offset in [0usize, 4, 8] {
        let buffer = read_u32(v + offset);
        if buffer != 0 {
            wave5_free(buffer);
        }
        write_u32(v + offset, 0);
    }
    platform::call1(FN_801B1180, inner);
    platform::call1(FN_801B1180, outer);
    0
}

