/// Runs the per-frame voice cost pass over the 32 JAS pools.
///
/// Clears the generation counter, invalidates the two per-voice tables, then
/// walks pool classes 31 down to 1. For every live object it adds the note's
/// fixed overhead, folds in its priority words from `0x8032E398`, and (for a
/// starting note) the sample-rate and `0x8032E418` costs. Notes below the
/// global ceiling are applied through [`fn_801a25c0`]; notes above it are
/// finished and moved to the pending list. Finally it walks pool 0, clears the
/// pending flags, flushes both tables and publishes the total cost.
///
/// # Original
/// - Ghidra: `FUN_801a2b10` at `0x801A2B10` (784 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a2b10_FUN_801a2b10.c`
///
/// # Arguments
/// - `voice_base`: base address added to the running cost (incoming `r3`,
///   hidden by the `0x802DCD6C` save-register prologue).
///
/// # Returns
/// The total cost left in `r13 - 0x5064` (the export prints `void`; the value
/// survives in `r3` through the restore epilogue).
///
/// # Side effects
/// Writes both per-voice tables, the pool lists, the generation counter, the
/// cost total, and brackets the pass with cache invalidate/flush calls.
///
/// # Safety
/// The pool lists and both per-voice tables must be live; the cost tables at
/// `0x8032E398`/`0x8032E418` must be readable.
///
/// # Confidence
/// medium - the loop, every offset and both table lookups are explicit; the
/// returned register and the `0x801AC440`/`0x801AC470` cache roles are inferred.
pub unsafe fn fn_801a2b10(voice_base: u32) -> u32 {
    let count = read_i32(SDA_VOICE_COUNT) as u32;
    let table = read_u32(SDA_VOICE_PARAM_TABLE);
    write_u32(SDA_VOICE_COST_COUNTER, 0);
    platform::call2(FN_801AC440, table, count.wrapping_mul(0x140));
    platform::call2(
        FN_801AC440,
        read_u32(SDA_VOICE_AUX_TABLE),
        count.wrapping_mul(0x40),
    );

    let mut cost = fn_801a0e50()
        .wrapping_add(count.wrapping_mul(600))
        .wrapping_add(voice_base)
        .wrapping_add(0x20);

    let mut class = 0x1Fi32;
    loop {
        let mut node = fn_801a00c0(class as u32);
        while node != 0 {
            let n = node as usize;
            if read_u16(n + 0x6C) == 1 {
                cost = cost.wrapping_add(0x81);
            }

            let slot = read_u32(n + 0x18);
            if read_u32(n + 0x20) != 0 {
                fn_801a2450(
                    read_u32(SDA_VOICE_PARAM_TABLE).wrapping_add(slot.wrapping_mul(0x140)),
                );
            }

            if read_u16(n + 0x38) == 1 {
                let mut extra = cost.wrapping_add(0x183);
                if read_u16(n + 0xE2) != 0 {
                    extra = cost.wrapping_add(0x2B8);
                }
                if read_u16(n + 0xEA) != 0 {
                    extra = extra.wrapping_add(0x400);
                }
                if read_u16(n + 0x6C) == 1 {
                    extra = extra.wrapping_add(0x1B);
                }

                let rate = read_u32(n + 0xCE).wrapping_mul(0x200).wrapping_add(0x8000) >> 16;
                let sample_cost = if read_u16(n + 0x30) == 0 {
                    rate.wrapping_add(0x619)
                } else if read_u16(n + 0x30) == 1 {
                    rate.wrapping_add(0x5BA)
                } else {
                    0x25D
                };

                let bits = read_u32(n + 0x34);
                cost = extra
                    .wrapping_add(sample_cost)
                    .wrapping_add(read_u32(DAT_8032E398 + ((bits >> 0x18) & 0x7C) as usize))
                    .wrapping_add(read_u32(DAT_8032E398 + ((bits >> 0x0E) & 0x7C) as usize))
                    .wrapping_add(read_u32(DAT_8032E398 + ((bits >> 0x13) & 0x7C) as usize))
                    .wrapping_add(read_u32(
                        DAT_8032E398 + ((bits & 0x1F).wrapping_mul(4)) as usize,
                    ));

                if read_u16(n + 0xFE) == 1 {
                    let mut mix = cost.wrapping_add(0x265);
                    let kind = read_u16(n + 0x13C);
                    if kind == 1 {
                        mix = cost.wrapping_add(0x2DB);
                    } else if kind == 2 {
                        mix = cost.wrapping_add(0x5A7);
                    }

                    let bits2 = read_u16(n + 0x100);
                    cost = read_u32(DAT_8032E418 + (((bits2 >> 0x0C) & 0xC) as usize))
                        .wrapping_add(read_u32(
                            DAT_8032E418 + (((bits2 >> 0x0A) & 0xC) as usize),
                        ))
                        .wrapping_add(mix)
                        .wrapping_add(read_u32(
                            DAT_8032E418 + (((bits2 >> 0x08) & 0xC) as usize),
                        ))
                        .wrapping_add(read_u32(
                            DAT_8032E418 + (((bits2 >> 0x06) & 0xC) as usize),
                        ))
                        .wrapping_add(read_u32(
                            DAT_8032E418 + (((bits2 >> 0x04) & 0xC) as usize),
                        ))
                        .wrapping_add(read_u32(
                            DAT_8032E418 + (((bits2 >> 0x02) & 0xC) as usize),
                        ))
                        .wrapping_add(read_u32(DAT_8032E418 + ((bits2 & 0xC) as usize)))
                        .wrapping_add(read_u32(
                            DAT_8032E418 + (((bits2 & 3) as usize) * 4),
                        ));
                }

                if cost < read_u32(SDA_VOICE_COST_LIMIT) {
                    fn_801a25c0(node);
                } else {
                    let block = read_u32(SDA_VOICE_PARAM_TABLE)
                        .wrapping_add(slot.wrapping_mul(0x140));
                    if read_u16(block as usize + 0x10) == 1 {
                        fn_801a2450(block);
                    }
                    write_u16(n + 0x38, 0);
                    write_u16(block as usize + 0x10, 0);
                    fn_801a0260(node);
                }
            } else {
                fn_801a25c0(node);
            }

            write_u32(n + 0x1C, 0);
            write_u32(n + 0x20, 0);
            node = read_u32(n);
        }

        class -= 1;
        if class == 0 {
            break;
        }
    }

    write_u32(SDA_VOICE_COST_TOTAL, cost);

    let mut node = fn_801a00c0(0);
    while node != 0 {
        let n = node as usize;
        let slot = read_u32(n + 0x18);
        let block = read_u32(SDA_VOICE_PARAM_TABLE).wrapping_add(slot.wrapping_mul(0x140));
        if read_u32(n + 0x20) != 0 {
            fn_801a2450(block);
        }
        write_u32(n + 0x20, 0);
        write_u16(block as usize + 0x10, 0);
        node = read_u32(n);
    }

    platform::call2(FN_801AC470, table, count.wrapping_mul(0x140));
    platform::call2(
        FN_801AC470,
        read_u32(SDA_VOICE_AUX_TABLE),
        count << 6,
    );

    cost
}

/// Allocates the base 3-voice sample buffers.
///
/// For each of three voices the function allocates a main buffer (`+0x00`,
/// length `+0x1C`), an optional second buffer (`+0x2C`, length `+0x40`), three
/// tap buffers (`+0x44`, lengths `+0x80+tap*4`), two history buffers (`+0x98`,
/// lengths `+0xC0+history*4`) and one extra buffer (`+0xC8`, length
/// `+0xEC+voice*4`). A zero allocation stops the walk and returns 0; earlier
/// buffers stay attached for the caller's free step.
///
/// # Original
/// - Ghidra: `FUN_801a3db0` at `0x801A3DB0` (372 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a3db0_FUN_801a3db0.c`
///
/// # Arguments
/// - `ctx`: buffer-table base. Ghidra loses the argument behind the
///   `0x802DCD64` save-register thunk; it is the incoming `r3`.
///
/// # Returns
/// 1 when all three voices are complete, 0 on the first failed allocation.
///
/// # Side effects
/// Writes every pointer slot and calls the JAS allocator hook.
///
/// # Safety
/// `ctx` must be writable and the allocator hook must be valid.
///
/// # Confidence
/// high - every offset, length and loop bound is explicit.
pub unsafe fn fn_801a3db0(ctx: u32) -> u32 {
    let p = ctx as usize;

    for voice in 0..3usize {
        let main = wave5_alloc(read_u32(p + 0x1C) << 2);
        write_u32(p + voice * 4, main);
        if main == 0 {
            return 0;
        }

        if read_u32(p + 0x40) == 0 {
            write_u32(p + voice * 4 + 0x2C, 0);
        } else {
            let second = wave5_alloc(read_u32(p + 0x40) << 2);
            write_u32(p + voice * 4 + 0x2C, second);
            if second == 0 {
                return 0;
            }
        }

        for tap in 0..3usize {
            let buffer = wave5_alloc(read_u32(p + 0x80 + tap * 4) << 2);
            write_u32(p + voice * 12 + tap * 4 + 0x44, buffer);
            if buffer == 0 {
                return 0;
            }
        }

        for history in 0..2usize {
            let buffer = wave5_alloc(read_u32(p + 0xC0 + history * 4) << 2);
            write_u32(p + voice * 8 + history * 4 + 0x98, buffer);
            if buffer == 0 {
                return 0;
            }
        }

        let extra = wave5_alloc(read_u32(p + 0xEC + voice * 4) << 2);
        write_u32(p + voice * 4 + 0xC8, extra);
        if extra == 0 {
            return 0;
        }
    }

    1
}

/// Computes the byte size of the 4-buffer sample set.
///
/// # Original
/// - Ghidra: `FUN_801a6090` at `0x801A6090` (40 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a6090_FUN_801a6090.c`
///
/// # Arguments
/// - `ctx`: voice block whose `+0x40` pitch field is scaled.
///
/// # Returns
/// `int(r2 - 0x50B0 * +0x40) << 4`.
///
/// # Side effects
/// None.
///
/// # Safety
/// Plain arithmetic on a readable voice block.
///
/// # Confidence
/// high - the single product and shift are explicit.
pub unsafe fn fn_801a6090(ctx: u32) -> i32 {
    let v = ctx as usize;
    ((read_f32(SDA2_VOICE_STREAM_SCALE) * read_f32(v + 0x40)) as i32).wrapping_shl(4)
}

/// Computes the byte size of the 4-voice sequence buffer set.
///
/// # Original
/// - Ghidra: `FUN_801a7690` at `0x801A7690` (96 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a7690_FUN_801a7690.c`
///
/// # Arguments
/// - `ctx`: voice block whose `+0xD4` pitch field is scaled.
///
/// # Returns
/// `(DAT_8033180C + int(scale * +0xD4) + four lengths) * 0x10`.
///
/// # Side effects
/// None.
///
/// # Safety
/// Plain arithmetic on a readable voice block.
///
/// # Confidence
/// high - every term and the multiplier are explicit.
pub unsafe fn fn_801a7690(ctx: u32) -> i32 {
    let v = ctx as usize;
    let scaled = (read_f32(SDA2_VOICE_SEQ_SCALE) * read_f32(v + 0xD4)) as i32;
    read_i32(DAT_8033180C)
        .wrapping_add(scaled)
        .wrapping_add(read_i32(DAT_80331870))
        .wrapping_add(read_i32(DAT_80331874))
        .wrapping_add(read_i32(DAT_80331878))
        .wrapping_add(read_i32(DAT_8033187C))
        .wrapping_mul(0x10)
}

/// Returns the fixed size constant of the 3-voice sequence set.
///
/// # Original
/// - Ghidra: `FUN_801a8400` at `0x801A8400` (12 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a8400_FUN_801a8400.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `0x9600`.
///
/// # Side effects
/// None.
///
/// # Safety
