/// Reads a big-endian 64-bit value as two words.
///
/// # Original
/// Host-side helper; models the `f64` constant loads in `sdata2`.
///
/// # Safety
/// `addr..addr+8` must be readable.
///
/// # Confidence
/// high - mechanical wrapper matching `write_u64`.
#[inline]
unsafe fn wave90_read_f64(addr: usize) -> f64 {
    let bits = ((read_u32(addr) as u64) << 32) | read_u32(addr + 4) as u64;
    f64::from_bits(bits)
}

/// Clears `words` 32-bit words starting at `base`.
///
/// # Original
/// Host-side helper; models the `do { *p++ = 0; } while (--n)` fills of
/// [`fn_801a2e70`], whose loop was unrolled eight words at a time by the
/// compiler.
///
/// # Safety
/// `base..base + words * 4` must be writable.
///
/// # Confidence
/// high - the fill is a plain zero store loop.
#[inline]
unsafe fn wave90_clear_words(base: usize, words: u32) {
    for index in 0..words as usize {
        write_u32(base + index * 4, 0);
    }
}

