/// unnamed `sdata2` limits and the four per-tap ramp entries are inferred from
/// the 2-tap sibling [`fn_801a73e0`].
pub unsafe fn fn_801a8150(voice: u32) -> u32 {
    let v = voice as usize;
    let slot = read_u32(v + 0xD0);
    let mut result = 0u32;

    if slot < 8 {
        let low = read_f32(SDA2_MIX4_LOW);
        let pitch = read_f32(v + 0xD8);
        if !(pitch < low) && !(read_f32(v + 0xD4) < pitch) {
            if read_u32(v + 0xDC) < 6 {
                if low <= read_f32(v + 0xE0) {
                    let high = read_f32(SDA2_MIX4_HIGH);
                    if !(read_f32(v + 0xE4) < low || high < read_f32(v + 0xE4))
                        && !(read_f32(v + 0xE8) < low || high < read_f32(v + 0xE8))
                        && !(read_f32(v + 0xEC) < low || high < read_f32(v + 0xEC))
                        && !(read_f32(v + 0xF0) < low || high < read_f32(v + 0xF0))
                        && !(read_f32(v + 0xFC) < low || high < read_f32(v + 0xFC))
                        && !(read_f32(v + 0x100) < low || high < read_f32(v + 0x100))
                    {
                        write_u32(v + 0x10, 0);
                        write_u32(v + 0x14, read_u32(JAS_MIX4_SLOT_TABLE + slot as usize * 4));
                        write_u32(
                            v + 0x1C,
                            if slot < 4 {
                                read_u32(SDA2_MIX4_SLOPE_LOW)
                            } else {
                                read_u32(SDA2_MIX4_SLOPE_HIGH)
                            },
                        );

                        let scale = read_f32(SDA2_MIX4_SCALE);
                        write_u32(v + 0x30, 0);
                        write_u32(
                            v + 0x34,
                            wave90_call_f64_i32(FN_802DCC4C, (scale * pitch) as f64) as u32,
                        );

                        let ramp_offset = wave90_read_f64(SDA2_MIX4_RAMP_OFFSET);
                        let ramp_scale = read_f32(SDA2_MIX4_RAMP_SCALE) as f64;
                        let pow_base = wave90_read_f64(SDA2_MIX4_POW_BASE);
                        let divisor = (scale as f64) * read_f32(v + 0xE0) as f64;
                        let selector = read_u32(v + 0xDC) as usize;

                        // observed: the loop runs twice, so this builder fills
                        // two ramp taps; the other half is written by its pair.
                        for tap in 0..2usize {
                            write_u32(v + 0x5C + tap * 4, 0);
                            let index =
                                read_u32(JAS_MIX4_TAP_TABLE + selector * 0x10 + tap * 4) as u32;
                            write_u32(v + 0x64 + tap * 4, index);
                            let ratio = (((ramp_scale
                                * ((((index as f64) - ramp_offset) as f32) as f64))
                                as f32) as f64)
                                / divisor;
                            let ramp = wave90_call_f64x2(FN_802E55A4, pow_base, ratio);
                            write_f32(v + 0x74 + tap * 4, ramp as f32);
                        }

                        write_u32(v + 0x9C, 0);
                        let table = selector * 0x10;
                        let high = read_f32(SDA2_MIX4_HIGH);
                        write_u32(v + 0xA4, read_u32(JAS_MIX4_WORD_A4 + table));
                        let ramp = high - read_f32(v + 0xE8);
                        write_u32(v + 0xA0, 0);
                        write_u32(v + 0xA8, read_u32(JAS_MIX4_WORD_A8 + table));
                        write_u32(v + 0xB4, read_u32(v + 0xE4));
                        let cap = read_f32(SDA2_MIX4_RAMP_CAP);
                        write_f32(v + 0xC8, ramp);
                        if cap < ramp {
                            write_f32(v + 0xC8, cap);
                        }

                        let default = read_u32(SDA2_MIX4_LOW);
                        write_u32(v + 0xB8, default);
                        write_u32(v + 0xBC, default);
                        write_u32(v + 0xC0, default);
                        write_u32(v + 0xC4, default);
                        result = 1;
                    }
                }
            }
        }
    }

    result
}

