    let a = read_f32(SDA2_MIX3_A);
    let b = read_f32(SDA2_MIX3_B);
    let blend = read_f32(s + 0xAC);
    let gain_direct = read_f32(s + 0xD0);
    let gain_mix = read_f32(s + 0xD4);
    let coef0 = read_f32(s + 0x18);
    let coef1 = read_f32(s + 0x64);
    let coef2 = read_f32(s + 0x68);
    let coef3 = read_f32(s + 0x9C);
    let offset = wave90_read_f64(SDA2_MIX3_OFFSET);

    let mut index = read_u32(s + 0xC) as usize;
    let mut side_index = read_u32(s + 0x28) as usize;
    let mut tap1 = read_u32(s + 0x4C) as usize;
    let mut tap2 = read_u32(s + 0x50) as usize;
    let mut tap3 = read_u32(s + 0x84) as usize;
    let mut tap4 = read_u32(s + 0x88) as usize;

