/// the fallback are unnamed `sdata2` words, and the first argument of the
/// export is unused.
pub unsafe fn fn_8019ef90(_mode: u32, out: usize, value: usize) {
    platform::call0(FN_80260860);
    let mode = call0_u32(FN_802610B0);
    if mode < 3 {
        let input = read_f32(value);
        let high = read_f32(SDA2_CLAMP_HIGH_518C);
        let low = read_f32(SDA2_CLAMP_LOW_517C);
        let mut result = high;
        if input <= high {
            result = input;
            if input < low {
                result = low;
            }
        }
        write_f32(out, result);
    } else {
        write_f32(out, read_f32(SDA2_CLAMP_FALLBACK_5198));
    }
}

/// Evaluates the line through `(x0, y0)` and `(x1, y1)` at `x`.
///
/// When both x endpoints coincide the function returns the average of the two
/// y values, scaled by `r2 - 0x5178`. The main path computes
/// `x * (y0 - y1) / (x0 - x1) + (x0 * y1 - x1 * y0) / (x0 - x1)` in
/// single precision, exactly as the export orders the casts.
///
/// # Original
/// - Ghidra: `FUN_8019f010` at `0x8019F010` (64 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8019f010_FUN_8019f010.c`
///
/// # Arguments
/// - `x`: sample position.
/// - `x0`: first endpoint x.
/// - `x1`: second endpoint x.
/// - `y0`: first endpoint y.
/// - `y1`: second endpoint y.
///
/// # Returns
/// The interpolated y, or `(y0 + y1) * scale` when the endpoints coincide.
///
/// # Side effects
/// None.
///
/// # Safety
/// None; pure arithmetic.
///
/// # Confidence
/// medium - every cast and the branch are literal; the role of the `sdata2`
/// scale in the degenerate branch is inferred to be `0.5` from the shape.
pub unsafe fn fn_8019f010(x: f64, x0: f64, x1: f64, y0: f64, y1: f64) -> f64 {
    if x0 == x1 {
        return (((y0 + y1) as f32) * read_f32(SDA2_INTERP_FLAT_SCALE)) as f64;
    }
    let width = (x0 - x1) as f32;
    let slope = ((x * ((y0 - y1) as f32 as f64)) as f32) / width;
    let intercept = (((x0 * y1) as f32) - ((x1 * y0) as f32)) / width;
    (slope + intercept) as f64
}

