/// ordinary `printf`-style reporter.
unsafe fn report1(format: usize) {
    platform::call1(STR_REPORT, format as u32);
}

/// Reports one line with one integer argument.
///
/// # Safety
/// See [`report1`].
unsafe fn report2(format: usize, a: u32) {
    platform::call2(STR_REPORT, format as u32, a);
}

/// Reports one line with two integer arguments.
///
/// # Safety
/// See [`report1`].
unsafe fn report3(format: usize, a: u32, b: u32) {
    platform::call3(STR_REPORT, format as u32, a, b);
}

/// Reports one line with three integer arguments.
///
/// # Safety
/// See [`report1`].
unsafe fn report4(format: usize, a: u32, b: u32, c: u32) {
    platform::call4(STR_REPORT, format as u32, a, b, c);
}

/// Copies `len` bytes with the boot-time `memcpy` at `0x80004364`.
///
/// # Safety
/// `dst..dst+len` writable, `src..src+len` readable, no overlap assumed.
unsafe fn copy_bytes(dst: u32, src: u32, len: u32) {
    platform::call3(FN_80004364, dst, src, len);
}

