/// Returns the console model code for the running board.
///
/// Two tables live in the body: the "development" table returns
/// `0x100000xx`/`0x10..0x21` depending on whether `0x801B25B0` reports the
/// retail clock (`0x04000000`), and the "plain" table returns only the
/// `0x10..0x21` half. The board halfword at `0x800030E6` selects which table
/// runs, and `0x100` is returned for the `0x300` board code.
///
/// # Original
/// - Ghidra: `FUN_801a9ee0` at `0x801A9EE0` (596 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a9ee0_FUN_801a9ee0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// A console/board type code; `0x10000002` when the application-info block or
/// its `+0x2C` word is null.
///
/// # Side effects
/// Calls `0x801B25B0` once on the paths that consult it.
///
/// # Safety
/// The boot-info words and the SDA application-info block must be mapped.
///
/// # Confidence
/// medium - every branch, comparison and return value is literal; the roles of
/// the two board words and of the `0x801B25B0` clock probe are `// inferred:`
/// from their use (the same words drive the banner in [`fn_801aa550`]).
pub unsafe fn fn_801a9ee0() -> u32 {
    let console = read_u32(OS_CONSOLE_TYPE_WORD);
    let app = read_u32(SDA_OS_APP_INFO);
    if app == 0 || read_u32(app as usize + 0x2C) == 0 {
        return 0x1000_0002;
    }

    let board = read_u16(OS_BOARD_TYPE_WORD) as u32;
    let mut use_plain = false;
    let mut use_kind = board & 0x8000 == 0;
    if board & 0x8000 != 0 {
        let code = board & 0x7FFF;
        let outside = 1 < code.wrapping_sub(2);
        // `0x201`/`0x202` jump straight to the development table.
        let dev_only = outside && code.wrapping_sub(0x201) < 2;
        if !dev_only {
            if outside && code != 0x203 {
                if code == 0x300 {
                    return 0x100;
                }
                use_kind = true;
            } else {
                use_plain = true;
            }
        }
    }

    if use_kind {
        let retail_clock = call0_u32(FN_801B25B0) == 0x0400_0000;
        return match console {
            0 => {
                if retail_clock {
                    0x10
                } else {
                    0x1000_0010
                }
            }
            1 => {
                if retail_clock {
                    0x11
                } else {
                    0x1000_0011
                }
            }
            2 => {
                if retail_clock {
                    0x12
                } else {
                    0x1000_0012
                }
            }
            0x10 => {
                if retail_clock {
                    0x20
                } else {
                    0x1000_0020
                }
            }
            0x11 => {
                if retail_clock {
                    0x21
                } else {
                    0x1000_0021
                }
            }
            kind if kind < 0x12 => read_u32(app as usize + 0x2C),
            _ => {
                if retail_clock {
                    0x21
                } else {
                    0x1000_0021
                }
            }
        };
    }

    if use_plain {
        // observed: the export repeats this table before the development table;
        // the fall-through for codes `3..0x0F` continues below.
        match console {
            0 => return 0x10,
            1 => return 0x11,
            2 => return 0x12,
            0x10 => return 0x20,
            0x11 => return 0x21,
            kind if kind > 0x11 => return 0x21,
            _ => {}
        }
    }

    match console {
        0 => 0x1000_0010,
        1 => 0x1000_0011,
        2 => 0x1000_0012,
        0x10 => 0x1000_0020,
        0x11 => 0x1000_0021,
        kind if kind < 0x12 => 0x100,
        _ => 0x1000_0021,
    }
}

/// Stores the MEM1 arena range back to memory and flushes its dirty tail.
///
/// The range runs from the arena low bound (`r13 - 0x6180`) to the arena word
/// (`r13 - 0x4FE8`). When the VBlank probe `0x801B3C90` reports a negative line
/// count and the write-back window at `0x8038E52C` is either unused or tagged
/// `0x30000000`, the whole range is stored and its top 256 KiB flushed;
/// otherwise only the part below the window limit and the part above the
/// window start are touched.
///
/// # Original
/// - Ghidra: `FUN_801aa140` at `0x801AA140` (476 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801aa140_FUN_801aa140.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Runs one `dcbst` pass over the arena and one `dcbf` pass over a 256 KiB tail.
///
/// # Safety
/// The two arena words must describe a mapped, writable MEM1 range.
///
/// # Confidence
/// medium - the arithmetic, the three duplicated store blocks and the flush
/// size are literal; the arena/window roles are `// inferred:` from the arena
/// accessors translated above, and one call prints only one operand (the size
/// is restored from the identical neighbouring block).
pub unsafe fn fn_801aa140() {
    let probe = call0_u32(FN_801B3C90) as i32;
    let limit = read_u32(OS_WRITEBACK_LIMIT);
    let low = fn_801abeb0();
    let high = fn_801abe80();

    let mut whole = probe >= 0 || limit == 0 || (limit & 0x3000_0000) != 0;
    let mut split = false;
    if !whole {
        if low < limit {
            if limit < high {
                split = true;
            } else {
                whole = true;
            }
        }
    }

    if whole {
        let size = fn_801abe80().wrapping_sub(fn_801abeb0());
        let low = fn_801abeb0();
        let mut flush_end = low;
        if 0x40000 < size {
            flush_end = low.wrapping_add(size - 0x40000);
        }
        platform::call2(FN_801AC530, low, size);
        platform::call2(FN_801AC470, flush_end, 0x40000);
    }

    if split {
        let size = limit.wrapping_sub(fn_801abeb0());
        let low = fn_801abeb0();
        let mut flush_end = low;
        if 0x40000 < size {
            flush_end = low.wrapping_add(size - 0x40000);
        }
        platform::call2(FN_801AC530, low, size);
        platform::call2(FN_801AC470, flush_end, 0x40000);
    }
}

/// Stores the MEM2 arena range back to memory and flushes its dirty tail.
///
/// The twin of [`fn_801aa140`] for the MEM2 arena words (`r13 - 0x4FE4` and
/// `r13 - 0x617C`); the window tag it tests is `0x10000000` instead of any
/// `0x30000000` bit. It also carries the extra `0x8038E530` step that stores
/// the window start separately.
///
/// # Original
/// - Ghidra: `FUN_801aa320` at `0x801AA320` (484 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801aa320_FUN_801aa320.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Runs `dcbst`/`dcbf` passes over the MEM2 arena range.
///
/// # Safety
/// The two arena words must describe a mapped, writable MEM2 range.
///
/// # Confidence
/// medium - same evidence quality as [`fn_801aa140`]; the extra window-start
/// pass and the `0x10000000` tag test are literal.
pub unsafe fn fn_801aa320() {
    let probe = call0_u32(FN_801B3C90) as i32;
    let limit = read_u32(OS_WRITEBACK_LIMIT);
    let low = fn_801abea0();
    let high = fn_801abe70();

    let mut whole = probe >= 0 || limit == 0 || (limit & 0x3000_0000) != 0x1000_0000;
    let mut split = false;
    if !whole {
        if low < limit {
            if limit < high {
                split = true;
            } else {
                whole = true;
            }
        }
    }

    if whole {
        let size = fn_801abe70().wrapping_sub(fn_801abea0());
        let low = fn_801abea0();
        let mut flush_end = low;
        if 0x40000 < size {
            flush_end = low.wrapping_add(size - 0x40000);
        }
        platform::call2(FN_801AC530, low, size);
        platform::call2(FN_801AC470, flush_end, 0x40000);
    }

    if split {
        let size = limit.wrapping_sub(fn_801abea0());
        let low = fn_801abea0();
        let mut flush_end = low;
        if 0x40000 < size {
            flush_end = low.wrapping_add(size - 0x40000);
        }
        platform::call2(FN_801AC530, low, size);
        platform::call2(FN_801AC470, flush_end, 0x40000);

        let start = read_u32(OS_WRITEBACK_START);
        let end = fn_801abe70();
        if start < end {
            let high = fn_801abe70();
            let mut flush_end = start;
            let size = high.wrapping_sub(start);
            if 0x40000 < size {
                flush_end = start.wrapping_add(size - 0x40000);
            }
            // unknown: the export prints this `dcbst` call with one operand;
            // the size is restored from the two blocks above, which store
            // `(start, high - start)`.
            platform::call2(FN_801AC530, start, size);
            platform::call2(FN_801AC470, flush_end, 0x40000);
        }
    }
}

/// Prints the console, firmware, memory and arena banner.
///
/// # Original
/// - Ghidra: `FUN_801aa550` at `0x801AA550` (676 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801aa550_FUN_801aa550.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Emits about a dozen report lines through `0x8015F730`.
///
/// # Safety
/// The RTC registers, the boot-info words and the report helper must be usable
/// (this runs once during boot).
///
/// # Confidence
/// medium - every string address, comparison and field extraction is literal
/// (the literals are quoted from the ELF); the numbering of the board codes is
/// `// inferred:` from the string each branch prints.
pub unsafe fn fn_801aa550() {
    report1(STR_REVOLUTION_OS);
    report3(STR_KERNEL_BUILT, STR_BUILD_DATE as u32, STR_BUILD_TIME as u32);
    report1(STR_CONSOLE_TYPE);

    let code = fn_801a9ee0();
    let family = code & 0xF000_0000;
    if family == 0 {
        match code {
            0x11 => report1(STR_BOARD_PRE1),
            0x12 => report1(STR_BOARD_PRE21),
            0x20 => report1(STR_BOARD_PRE22),
            0x100 => report1(SDA_BOARD_TEXT_100),
            _ => report2(STR_BOARD_RETAIL, code),
        }
    } else if family == 0x1000_0000 {
        match code {
            0x1000_0021 => report1(STR_BOARD_NDEV21),
            0x1000_0020 => report1(STR_BOARD_NDEV20),
            0x1000_0012 => report1(STR_BOARD_NDEV12),
            0x1000_0011 => report1(STR_BOARD_NDEV11),
            0x1000_0010 => report1(STR_BOARD_NDEV10),
            0x1000_0008 => report1(STR_BOARD_EMULATOR),
            _ => report2(STR_BOARD_EMU_PLATFORM, code),
        }
    } else if family == 0x2000_0000 {
        report2(STR_BOARD_TDEV, (code & 0x0FFF_FFFF).wrapping_sub(3));
    } else {
        report2(SDA_BOARD_TEXT_OTHER, code);
    }

    let date = read_u32(RTC_COUNTER_A);
    let packed = read_u32(RTC_COUNTER_B);
    report4(
        STR_FIRMWARE,
        (date >> 16) & 0xFF,
        (date >> 8) & 0xFF,
        date & 0xFF,
    );
    // observed: the packed BCD word is decoded nibble by nibble; the third
    // field adds the 2000 epoch.
    report4(
        STR_FIRMWARE_DATE,
        (((packed >> 16) & 0xF).wrapping_add(((packed >> 20) & 0xF).wrapping_mul(10))) & 0xFF,
        (((packed >> 8) & 0xF).wrapping_add(((packed >> 12) & 0xF).wrapping_mul(10))) & 0xFF,
        (packed & 0xF)
            .wrapping_add(((packed >> 4) & 0xF).wrapping_mul(10))
            .wrapping_add(2000),
    );

    let upper = call0_u32(FN_801B25D0);
    let lower = call0_u32(FN_801B25C0);
    report2(STR_MEMORY, (lower.wrapping_add(upper)) >> 20);

    report3(STR_MEM1_ARENA, fn_801abe90(), fn_801abe60());
    report3(STR_MEM2_ARENA, fn_801abea0(), fn_801abe70());
}

/// Installs the fifteen exception vector slots and the OSDBIntegrator hook.
///
/// # Original
/// - Ghidra: `FUN_801aad60` at `0x801AAD60` (640 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801aad60_FUN_801aad60.c`
/// - Removed: the `bl 0x802DCD58` (`__savegprlr_20`) prologue and the
///   `bl 0x802DCDA4` (`__restgprlr_20`) epilogue; both only save and restore
///   non-volatile registers.
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Copies the integrator stub to `0x80000060`, copies one 0x98-byte handler per
/// exception, publishes the handler table at `0x80003000`, and reports each
/// exception it takes over or hands to TRK.
///
/// # Safety
/// Must run once during boot with the low-memory vector area writable and
/// instruction cache coherency available.
///
/// # Confidence
/// medium - every guard, copy, flush and store is literal; the identity of
/// `0x801BB9C0`/`0x801BB9E0` and the `r13 - 0x5014` table are `// inferred:`
/// from the `boot_info_flag` and `os_report` bodies already in `runtime::os`.
pub unsafe fn fn_801aad60() {
    let saved_mask = read_u32(OS_EXCEPTION_MASK);

    if read_u32(OS_OSDB_INTEGRATOR) == 0 {
        report1(STR_INSTALL_OSDB);
        copy_bytes(OS_OSDB_INTEGRATOR as u32, 0x801A_AFE0, 0x24);
        platform::call2(FN_801AC4D0, OS_OSDB_INTEGRATOR as u32, 0x24);
        platform::call2(FN_801AC560, OS_OSDB_INTEGRATOR as u32, 0x24);
    }

    let mut index = 0u32;
    while index < 0xF {
        let pool = read_u32(SDA_OS_EXCEPTION_POOL);
        let already_hooked = pool != 0
            && read_u32(pool as usize) >= 2
            && platform::call1(FN_801BB9C0, index & 0xFF) != 0;
        if already_hooked {
            report2(STR_EXCEPTION_COMMANDEERED, index & 0xFF);
        } else {
            write_u32(OS_EXCEPTION_MASK, saved_mask | (index & 0xFF));
            if call0_u32(FN_801BB9C0) != 0 {
                report2(STR_EXCEPTION_VECTORED, index & 0xFF);
                copy_bytes(EXCEPTION_STUB_WORD as u32, DEBUGGER_ENTRY_WORD as u32, 4);
            } else {
                // observed: the export's one-iteration do/while writes the
                // `nop` word `0x60000000` into the stub.
                write_u32(EXCEPTION_STUB_WORD, 0x6000_0000);
            }
            let offset = (index & 0xFF) as usize * 4;
            let handler = read_u32(EXCEPTION_HANDLER_TABLE + offset).wrapping_sub(0x8000_0000);
            copy_bytes(handler, EXCEPTION_TEMPLATE as u32, 0x98);
            platform::call2(FN_801AC4D0, handler, 0x98);
            platform::call2(FN_801AC560, handler, 0x98);
        }
        index += 1;
    }

    write_u32(SDA_OS_EXCEPTION_TABLE, EXCEPTION_SLOT_TABLE as u32);
    // observed: the export lists fifteen unrolled stores at `+0x00..+0x38`.
    let mut offset = 0usize;
    while offset <= 0x38 {
        write_u32(EXCEPTION_SLOT_TABLE + offset, EXCEPTION_VECTOR_STUB as u32);
        offset += 4;
    }

    write_u32(OS_EXCEPTION_MASK, saved_mask);
    report1(STR_EXCEPTIONS_READY);
}

/// `0xCD800180` - Hollywood register whose bits 8..15 are replaced by the mode
/// argument; `// unknown:` the register has no name in this tree.
const HW_MODE_REG: usize = 0xCD80_0180;
/// `0xCD8001CC` - Hollywood timing register; the low 27 bits are replaced by a
/// mode-dependent constant (`0x4640FC0` or `0x4B0FFCE`).
const HW_TIMING_REG: usize = 0xCD80_01CC;
/// `0xCD8001D0` - Hollywood control register toggled four times by
/// [`fn_801abf60`].
const HW_CONTROL_REG: usize = 0xCD80_01D0;

/// Reads a big-endian 64-bit value as an `f64`.
///
/// # Original
/// Host-side helper; models the `lfd` used by the context dump.
///
/// # Safety
/// `addr..addr+8` must be readable.
///
/// # Confidence
/// high - mechanical wrapper over [`read_u32`].
unsafe fn read_f64(addr: usize) -> f64 {
    f64::from_bits(((read_u32(addr) as u64) << 32) | read_u32(addr + 4) as u64)
}

/// Calls a function that takes one `f64` and returns a word.
///
/// # Original
/// Host-side helper; models the `f1` argument of `0x802DCC4C`.
///
/// # Safety
/// `addr` must point to a function with this ABI.
///
/// # Confidence
/// high - mechanical wrapper, same shape as [`call_f32_1`].
unsafe fn call_f64_1(addr: usize, value: f64) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f64) -> u32);
    f(value)
}

/// Programs the Hollywood mode/timing registers with bus-clock delays.
///
/// The routine clears bits 8..15 of `0xCD800180`, installs one of two timing
/// constants in `0xCD8001CC`, then walks four bits of `0xCD8001D0`. Each step
/// spins until at least 100 (or 1,000) microseconds have elapsed, measured as
/// `(tick_now - tick_start) * 8 / (bus_clock / 500000)`.
///
/// # Original
/// - Ghidra: `FUN_801abf60` at `0x801ABF60` (544 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801abf60_FUN_801abf60.c`
///
/// # Arguments
/// - `mode`: zero selects the `0x4640FC0` timing word, any other value the
///   `0x4B0FFCE` word; the low byte is also shifted into bits 8..15 of
///   `0xCD800180`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes three memory-mapped registers and busy-waits on the timebase.
///
/// # Safety
/// The Hollywood register block must be mapped; `0x801B5FA0` must read the
/// timebase.
///
/// # Confidence
/// medium - every mask, constant and delay threshold is literal; the register
/// roles are `// unknown:` and the tick source is an `// inferred:` timebase.
pub unsafe fn fn_801abf60(mode: u32) {
    let bus_divisor = read_u32(OS_BUS_CLOCK) / 500_000;

    write_u32(
        HW_MODE_REG,
        (read_u32(HW_MODE_REG) & 0xFFFF_FE7F) | (mode << 8),
    );
    write_u32(HW_CONTROL_REG, read_u32(HW_CONTROL_REG) & 0x3FFF_FFFF);

    let start = call0_u32(FN_801B5FA0);
    while call0_u32(FN_801B5FA0)
        .wrapping_sub(start)
        .wrapping_mul(8)
        / bus_divisor
        < 100
    {}

    if mode == 0 {
        write_u32(HW_TIMING_REG, (read_u32(HW_TIMING_REG) & 0xF800_0000) | 0x0464_0FC0);
    } else {
        write_u32(HW_TIMING_REG, (read_u32(HW_TIMING_REG) & 0xF800_0000) | 0x04B0_FFCE);
    }

    let start = call0_u32(FN_801B5FA0);
    while call0_u32(FN_801B5FA0)
        .wrapping_sub(start)
        .wrapping_mul(8)
        / bus_divisor
        < 100
    {}

    write_u32(HW_CONTROL_REG, read_u32(HW_CONTROL_REG) & 0xEFFF_FFFF);

    let start = call0_u32(FN_801B5FA0);
    while call0_u32(FN_801B5FA0)
        .wrapping_sub(start)
        .wrapping_mul(8)
        / bus_divisor
        < 1000
    {}

    write_u32(HW_CONTROL_REG, read_u32(HW_CONTROL_REG) & 0xBFFF_FFFF | 0x4000_0000);

    let start = call0_u32(FN_801B5FA0);
    while call0_u32(FN_801B5FA0)
        .wrapping_sub(start)
        .wrapping_mul(8)
        / bus_divisor
        < 1000
    {}

    write_u32(HW_CONTROL_REG, read_u32(HW_CONTROL_REG) & 0x7FFF_FFFF | 0x8000_0000);

    let start = call0_u32(FN_801B5FA0);
    while call0_u32(FN_801B5FA0)
        .wrapping_sub(start)
        .wrapping_mul(8)
        / bus_divisor
        < 1000
    {}
}

/// Tail-calls `0x801ACC00` with the first argument repeated as the third.
///
/// # Original
/// - Ghidra: `FUN_801acd30` at `0x801ACD30` (8 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801acd30_FUN_801acd30.c`
///
/// # Arguments
/// - `first`: first word, also passed in `r5`.
/// - `second`: second word.
///
/// # Returns
/// Nothing; the original is a tail branch (`b 0x801ACC00`), not a call.
///
/// # Side effects
/// Whatever `0x801ACC00` does with the three words.
///
/// # Safety
/// `0x801ACC00` must be the intended three-argument entry point.
///
/// # Confidence
/// high - the export shows the three-argument call and the raw bytes are
/// `addi r5,r3,0; b 0x801ACC00`.
pub unsafe fn fn_801acd30(first: u32, second: u32) {
    platform::call3(FN_801ACC00, first, second, first);
}

/// Dumps the live `OSContext` through the report helper.
///
/// Prints the sixteen GPR pairs, LR/CR, SRR0/SRR1, the eight GQRs, and - when
/// the context's `+0x1A2` FP-available bit is set - the thirty-two FPRs, the
/// paired singles and finally the stack back chain. Reading the FP registers
/// needs a scratch context: the routine masks interrupts, installs a zeroed
/// scratch block through `0x801ACD40`, and restores the previous context and
/// interrupt state afterwards.
///
/// # Original
/// - Ghidra: `FUN_801ad070` at `0x801AD070` (608 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ad070_FUN_801ad070.c`
/// - Removed: the `bl 0x802DCD6C` (`__savegprlr_25`) prologue and the
///   `bl 0x802DCDB8` (`__restgprlr_25`) epilogue; the prologue only saved the
///   incoming `r3`, now the `context` parameter.
///
/// # Arguments
/// * `context` - live `OSContext` (incoming `r3`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// About 40 report lines, two context installs, and an interrupt-mask round
/// trip.
///
/// # Safety
/// The context and its FP save area must be readable, and the report helper
/// must be usable at this point in boot.
///
/// # Confidence
/// medium - every offset, loop bound and format call is literal; the two
/// zeroed halfwords and the FPR/PSF split are `// inferred:` from the offsets,
/// and the 64-bit FPR arguments go through `0x802DCC4C` as `f64`.
pub unsafe fn fn_801ad070(context: usize) {
    report2(STR_CONTEXT_BANNER, context as u32);

    let mut i = 0usize;
    while i < 0x10 {
        let left = read_u32(context + i * 4);
        let right = read_u32(context + (i + 0x10) * 4);
        platform::call7(
            STR_REPORT,
            STR_CONTEXT_GPR as u32,
            i as u32,
            left,
            left,
            (i + 0x10) as u32,
            right,
            right,
        );
        i += 1;
    }

    platform::call3(
        STR_REPORT,
        STR_CONTEXT_LR_CR as u32,
        read_u32(context + 0x84),
        read_u32(context + 0x80),
    );
    platform::call3(
        STR_REPORT,
        STR_CONTEXT_SRR as u32,
        read_u32(context + 0x198),
        read_u32(context + 0x19C),
    );

    report1(STR_CONTEXT_GQR);
    let mut i = 0usize;
    while i < 4 {
        platform::call5(
            STR_REPORT,
            STR_CONTEXT_GQR_LINE as u32,
            i as u32,
            read_u32(context + 0x1A4 + i * 4),
            (i + 4) as u32,
            read_u32(context + 0x1B4 + i * 4),
        );
        i += 1;
    }

    if read_u16(context + 0x1A2) & 1 != 0 {
        let saved_interrupts = call0_u32(FN_801B1140);
        let previous_context = read_u32(OS_ACTIVE_CONTEXT);
        let mut scratch = [0u8; 0x2E8];
        let scratch_ptr = scratch.as_mut_ptr() as u32;
        // inferred: the export zeroes `local_148`/`local_146`, the halfwords
        // that follow the scratch block, before installing it.
        write_u16(scratch_ptr as usize + 0x1A0, 0);
        write_u16(scratch_ptr as usize + 0x1A2, 0);
        if scratch_ptr == read_u32(OS_FP_CONTEXT) {
            write_u32(OS_FP_CONTEXT, 0);
        }
        platform::call1(FN_801ACD40, scratch_ptr);

        report1(STR_CONTEXT_FPR);
        let mut i = 0usize;
        while i < 0x20 {
            let first = read_f64(context + 0x90 + i * 8);
            let second = read_f64(context + 0x98 + i * 8);
            platform::call5(
                STR_REPORT,
                STR_CONTEXT_FPR_LINE as u32,
                i as u32,
                call_f64_1(FN_802DCC4C, first),
                (i + 1) as u32,
                call_f64_1(FN_802DCC4C, second),
            );
            i += 2;
        }

        report1(STR_CONTEXT_PSF);
        let mut i = 0usize;
        while i < 0x20 {
            let first = read_f64(context + 0x1C8 + i * 8);
            let second = read_f64(context + 0x1D0 + i * 8);
            platform::call5(
                STR_REPORT,
                STR_CONTEXT_PSF_LINE as u32,
                i as u32,
                call_f64_1(FN_802DCC4C, first),
                (i + 1) as u32,
                call_f64_1(FN_802DCC4C, second),
            );
            i += 2;
        }

        write_u16(scratch_ptr as usize + 0x1A0, 0);
        write_u16(scratch_ptr as usize + 0x1A2, 0);
        if scratch_ptr == read_u32(OS_FP_CONTEXT) {
            write_u32(OS_FP_CONTEXT, 0);
        }
        platform::call1(FN_801ACD40, previous_context);
        platform::call1(FN_801B1180, saved_interrupts);
    }

    report1(STR_CONTEXT_STACK);
    let mut frame = read_u32(context + 4);
    let mut depth = 0u32;
    while frame != 0 && frame != 0xFFFF_FFFF && depth < 0x10 {
        report4(
            STR_CONTEXT_STACK_LINE,
            frame,
            read_u32(frame as usize),
            read_u32(frame as usize + 4),
        );
        frame = read_u32(frame as usize);
        depth += 1;
    }
}

/// `0x801B32B0` - returns two SDA words through two output pointers.
const FN_801B32B0: usize = 0x801B_32B0;
/// `0x801AC530` - `dcbst` block loop (the `dc_store_range` of `runtime::os`).
const FN_801AC530: usize = 0x801A_C530;
/// `0x801B3C90` - latched vertical-timing probe; negative outside the blanking
/// window.
const FN_801B3C90: usize = 0x801B_3C90;
/// `0x801B25D0` - upper memory-arena bound used by the memory banner.
const FN_801B25D0: usize = 0x801B_25D0;
/// `0x801B25C0` - lower memory-arena bound used by the memory banner.
const FN_801B25C0: usize = 0x801B_25C0;

/// Builds the `argv` block for the loader: packs the strings below a 0x2000-byte
/// scratch area and copies the offset array above them.
///
/// The 64-bit pair returned by `0x802DCD6C` supplies the scratch base (high
/// word) and the entry count (low word). Each entry is copied downward from
/// the top of the scratch area, then the `count + 1` offsets are copied to a
/// four-byte-aligned position below the packed strings; the word in front of
/// them holds `count`, and its offset from the base is published at `base + 8`.
///
/// # Original
/// - Ghidra: `FUN_801adba0` at `0x801ADBA0` (384 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801adba0_FUN_801adba0.c`
/// - Removed: the `bl 0x802DCD6C` (`__savegprlr_25`) prologue and the
///   `bl 0x802DCDB8` (`__restgprlr_25`) epilogue; the prologue only saved the
///   incoming `r3`/`r4` (`base`/`count`) and the epilogue left `1` in `r3`.
///
/// # Arguments
/// - `base`: scratch base (incoming `r3`).
/// - `count`: entry count (incoming `r4`).
/// - `argv`: null-terminated array of string pointers, `count + 1` words long.
///
/// # Returns
/// `1`, as the epilogue does.
///
/// # Side effects
/// Clears the 0x2000-byte scratch block, rewrites the caller's pointer array
/// with base-relative offsets, and publishes the offset vector at `base + 8`.
///
/// # Safety
/// `argv` must hold `count + 1` readable/writable words and the scratch block
/// must be a writable 0x2000-byte region.
///
/// # Confidence
/// medium - the two loops, the alignment mask and the published offsets are
/// literal; the string helper `0x802DC69C` and copy helper `0x802E1938` are
/// identified from their translated bodies (`strlen`/`strcpy`).
pub unsafe fn fn_801adba0(base: u32, count: u32, argv: u32) -> u32 {
    platform::call3(FN_800046B4, base, 0, 0x2000);
    if count == 0 {
        write_u32(base as usize + 8, 0);
    } else {
        let mut cursor = base.wrapping_add(0x2000);
        let mut index = count;
        loop {
            index = index.wrapping_sub(1);
            if index == u32::MAX {
                break;
            }
            let slot = argv.wrapping_add(index.wrapping_mul(4));
            let text = read_u32(slot as usize);
            let len = platform::call1(FN_802DC69C, text);
            cursor = cursor.wrapping_sub(len.wrapping_add(1));
            platform::call2(FN_802E1938, cursor, text);
            write_u32(slot as usize, cursor.wrapping_sub(base));
        }

        let items = count.wrapping_add(1);
        let block = base
            .wrapping_add(cursor.wrapping_sub(base) & 0xFFFF_FFFC)
            .wrapping_sub(items.wrapping_mul(4));
        let mut k = 0u32;
        while k < items {
            let source = read_u32(argv as usize + k as usize * 4);
            write_u32(block as usize + k as usize * 4, source);
            k += 1;
        }
        write_u32(block as usize - 4, count);
        write_u32(
            base as usize + 8,
            block.wrapping_sub(4).wrapping_sub(base),
        );
    }
    1
}

/// Same as [`fn_801adba0`], but stores even-indexed entries as hex text.
///
/// Entry 0 and 1 and every odd index are narrow strings (`strlen`/`strcpy`);
/// every even index from 2 upwards is a UTF-16BE string, whose length is taken
/// with `0x802E441C` and which is rendered as lowercase hex by `0x801ADD20`
/// (four text bytes per wide character).
