/// `r2 - 0x513C` - band-gain multiplier of the 3-channel effect mixer.
const SDA2_FX3_MIX: usize = SDA2_BASE - 0x513C;
/// `r2 - 0x5138` - cross-feed coefficient of the four-way mono fold.
const SDA2_FX3_FEED: usize = SDA2_BASE - 0x5138;
/// `r2 - 0x5130` - `f64` bias of the integer-to-float sample conversion.
const SDA2_FX3_BIAS: usize = SDA2_BASE - 0x5130;
/// `r2 - 0x5144` - additive bias of the delay-line sum.
/// `// unknown:` the value is not known to be zero.
const SDA2_FX3_DELAY: usize = SDA2_BASE - 0x5144;

/// `r2 - 0x5100` - upper band limit of the 4-channel effect mixer.
const SDA2_FX4_LIMIT: usize = SDA2_BASE - 0x5100;
/// `r2 - 0x50FC` - band-gain multiplier of the 4-channel effect mixer.
const SDA2_FX4_MIX: usize = SDA2_BASE - 0x50FC;
/// `r2 - 0x50F8` - cross-feed coefficient of the 4-channel mixer.
const SDA2_FX4_FEED: usize = SDA2_BASE - 0x50F8;
/// `r2 - 0x50F0` - `f64` bias of the 4-channel sample conversion.
const SDA2_FX4_BIAS: usize = SDA2_BASE - 0x50F0;
/// `r2 - 0x5104` - additive bias of the 4-channel delay-line sum.
const SDA2_FX4_DELAY: usize = SDA2_BASE - 0x5104;

