const FN_801AF7C0: usize = 0x801A_F7C0;

/// Advances one ring index in place, wrapping it at `length`.
///
/// `state + index_off` holds the cursor and `state + len_off` the ring length.
///
/// # Safety
/// Both words must be readable and the index word writable.
#[inline]
unsafe fn wave101_bump(state: usize, index_off: usize, len_off: usize) {
    let next = read_u32(state + index_off).wrapping_add(1);
    if read_u32(state + len_off) <= next {
        write_u32(state + index_off, 0);
    } else {
        write_u32(state + index_off, next);
    }
}

/// Mixes 96 frames of three channels through the float delay/filter chain.
///
/// For every frame and channel the kernel:
///
/// 1. reads one sample from the channel's cursor plane (adding the optional
///    extra plane), converts it with the `f64` bias at `r2 - 0x5130`, and
///    writes it into the third tap slot of the channel's plane;
/// 2. optionally swaps it through the sidechain plane at `+0x2C + 4*channel`
///    using the shared index `+0x38` and length `+0x3C`;
/// 3. runs the three delay lines at `+0x44 + 12*channel` with the shared
///    indices `+0x68`/`+0x6C`/`+0x70` and the three `int` coefficients at
///    `+0x8C`/`+0x90`/`+0x94`;
/// 4. runs the two one-pole filters at `+0x98 + 8*channel`, folds them with
///    the `r2 - 0x5144` bias, the `+0xF8` feedback and the envelope at
///    `+0xFC + 4*channel`, and writes the result into the output plane at
///    `+0xC8 + 4*channel`;
/// 5. folds the three channel results with the `r2 - 0x5138` cross-feed
///    coefficient and writes the gained values back into the three cursor
///    planes (and the optional auxiliary planes).
///
/// Every per-channel index is then advanced and wrapped by its length word.
///
/// # Original
/// - Ghidra: `FUN_801a3880` at `0x801a3880` (1316 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a3880_FUN_801a3880.c`
/// - Removed: the `bl 0x802DCDB8` (`__restgprlr_25`) epilogue; it only
///   restores the saved registers. The `bl 0x802DCD6C` prologue is likewise
///   register bookkeeping and takes no part in the mix.
///
/// # Arguments
/// - `planes`: three-word vector of read/write cursor pointers (`r3`).
/// - `state`: mixer state (`r4`); the word offsets above are byte offsets.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the three tap, sidechain, delay, filter and output planes, the
/// cursor words and the envelope words of `state`.
///
/// # Safety
/// Every plane must hold at least 96 frames, every index must be inside its
/// ring, and `state` must be readable to `+0x148`.
///
/// # Confidence
/// medium - the loop, every store, the counter wrap and the fold order are
/// literal; the field roles, the `int`-to-`float` coefficient units and the
/// `sdata2` constant roles are inferred from the sibling mixers.
pub unsafe fn fn_801a3880(planes: u32, state: u32) {
    let s = state as usize;

    if read_u32(s + 0x10C) != 0 {
        write_u32(s + 0x10C, read_u32(s + 0x10C) & 0xFFFF_FFFD);
        return;
    }

    let extra_in = read_u32(s + 0x138);
    let extra_out = read_u32(s + 0x13C);

    let mut input = [
        read_u32(planes as usize) as usize,
        read_u32(planes as usize + 4) as usize,
        read_u32(planes as usize + 8) as usize,
    ];
    let mut extra = [0usize; 3];
    let mut aux = [0usize; 3];
    if extra_in != 0 {
        for channel in 0..3 {
            extra[channel] = read_u32(extra_in as usize + channel * 4) as usize;
        }
    }
    if extra_out != 0 {
        for channel in 0..3 {
            aux[channel] = read_u32(extra_out as usize + channel * 4) as usize;
        }
    }

    let limit = read_f32(SDA2_FX3_LIMIT);
    let blend = read_u32(s + 0x108) as f32;
    let mix = read_f32(SDA2_FX3_MIX);
    let direct_gain = read_u32(s + 0x134) as f32;
    let feedback = read_u32(s + 0xF8) as f32;
    let cross = read_f32(SDA2_FX3_FEED) * read_u32(s + 0x12C) as f32;
    let delay_bias = read_f32(SDA2_FX3_DELAY);
    let offset = wave90_read_f64(SDA2_FX3_BIAS);
    let out_gain = read_u32(s + 0x140) as f32;
    let aux_gain = read_u32(s + 0x144) as f32;

    for _ in 0..0x60 {
        let mut acc = [0f32; 3];

        for channel in 0..3usize {
            let mut raw = read_i32(input[channel]);
            if extra_in != 0 {
                raw = raw.wrapping_add(read_i32(extra[channel]));
                extra[channel] += 4;
            }
            let mut sample = (((raw as u32) ^ 0x8000_0000) as f64 - offset) as f32;

            let base = read_u32(s + channel * 4) as usize;
            let tap_index_0 = read_u32(s + 0x0C) as usize;
            let tap_index_1 = read_u32(s + 0x10) as usize;
            let tap_index_2 = read_u32(s + 0x14) as usize;
            let gain_0 = read_u32(s + 0x20) as f32;
            let tap_0 = read_f32(base + tap_index_0 * 4);
            let gain_1 = read_u32(s + 0x24) as f32;
            let tap_1 = read_f32(base + tap_index_1 * 4);
            let gain_2 = read_u32(s + 0x28) as f32;
            let tap_2 = read_f32(base + tap_index_2 * 4);
            write_f32(base + tap_index_2 * 4, sample);

            if read_u32(s + 0x3C) != 0 {
                let plane = read_u32(s + 0x2C + channel * 4) as usize;
                let index = read_u32(s + 0x38) as usize;
                let previous = read_f32(plane + index * 4);
                write_f32(plane + index * 4, sample);
                sample = previous;
            }
            let value = sample;

            let delay_plane_0 = read_u32(s + 0x44 + channel * 12) as usize;
            let delay_index_0 = read_u32(s + 0x68) as usize;
            let delay_0 = read_f32(delay_plane_0 + delay_index_0 * 4);
            write_f32(
                delay_plane_0 + delay_index_0 * 4,
                value + delay_0 * read_u32(s + 0x8C) as f32,
            );

            let delay_plane_1 = read_u32(s + 0x48 + channel * 12) as usize;
            let delay_index_1 = read_u32(s + 0x6C) as usize;
            let delay_1 = read_f32(delay_plane_1 + delay_index_1 * 4);
            write_f32(
                delay_plane_1 + delay_index_1 * 4,
                value + delay_1 * read_u32(s + 0x90) as f32,
            );

            let delay_plane_2 = read_u32(s + 0x4C + channel * 12) as usize;
            let delay_index_2 = read_u32(s + 0x70) as usize;
            let delay_2 = read_f32(delay_plane_2 + delay_index_2 * 4);
            write_f32(
                delay_plane_2 + delay_index_2 * 4,
                value + delay_2 * read_u32(s + 0x94) as f32,
            );

            let filter_plane_0 = read_u32(s + 0x98 + channel * 8) as usize;
            let filter_index_0 = read_u32(s + 0xB0) as usize;
            let filter_0 = read_f32(filter_plane_0 + filter_index_0 * 4);
            let sum = delay_bias + delay_0 + delay_1 + delay_2 + filter_0 * feedback;
            write_f32(filter_plane_0 + filter_index_0 * 4, sum);

            let filter_plane_1 = read_u32(s + 0x9C + channel * 8) as usize;
            let filter_index_1 = read_u32(s + 0xB4) as usize;
            let filter_1 = read_f32(filter_plane_1 + filter_index_1 * 4);
            let filtered = (filter_0 - sum * feedback) + filter_1 * feedback;
            write_f32(filter_plane_1 + filter_index_1 * 4, filtered);

            let envelope = (limit - blend) * (filter_1 - filtered * feedback)
                + blend * read_u32(s + 0xFC + channel * 4) as f32;
            write_u32(s + 0xFC + channel * 4, envelope as i32 as u32);

            let out_plane = read_u32(s + 0xC8 + channel * 4) as usize;
            let out_index = read_u32(s + 0xD4 + channel * 4) as usize;
            let out_previous = read_f32(out_plane + out_index * 4);
            let out_value = envelope + out_previous * feedback;
            write_f32(out_plane + out_index * 4, out_value);

            let next = out_index.wrapping_add(1);
            if read_u32(s + 0xE0 + channel * 4) as usize <= next {
                write_u32(s + 0xD4 + channel * 4, 0);
            } else {
                write_u32(s + 0xD4 + channel * 4, next as u32);
            }

            // observed: the exported sum order is tap2, tap0, tap1.
            acc[channel] = (out_previous - out_value * feedback) * mix * direct_gain
                + gain_2 * tap_2
                + gain_0 * tap_0
                + gain_1 * tap_1;
        }

        let mono = acc[0] + (acc[1] + acc[2]) * cross;
        let mid = acc[1] + (acc[0] + acc[2]) * cross;
        let lower = acc[2] + (acc[0] + acc[1]) * cross;

        let out_0 = input[0];
        let out_1 = input[1];
        let out_2 = input[2];
        input[0] += 4;
        input[1] += 4;
        input[2] += 4;

        write_u32(out_0, (mono * out_gain) as i32 as u32);
        write_u32(out_1, (mid * out_gain) as i32 as u32);
        write_u32(out_2, (lower * out_gain) as i32 as u32);

        if extra_out != 0 {
            write_u32(aux[0], (mono * aux_gain) as i32 as u32);
            write_u32(aux[1], (mid * aux_gain) as i32 as u32);
            write_u32(aux[2], (lower * aux_gain) as i32 as u32);
            aux[0] += 4;
            aux[1] += 4;
            aux[2] += 4;
        }

        wave101_bump(s, 0x0C, 0x18);
        wave101_bump(s, 0x10, 0x18);
        wave101_bump(s, 0x14, 0x18);
        if read_u32(s + 0x3C) != 0 {
            wave101_bump(s, 0x38, 0x3C);
        }
        wave101_bump(s, 0x68, 0x74);
        wave101_bump(s, 0x6C, 0x78);
        wave101_bump(s, 0x70, 0x7C);
        wave101_bump(s, 0xB0, 0xB8);
        wave101_bump(s, 0xB4, 0xBC);
    }
}

/// Mixes 96 frames of four channels through the float delay/filter chain.
///
/// The 4-channel twin of [`fn_801a3880`]. The state block moves up by one
/// channel: active flag `+0x13C`, blend `+0x138`, direct gain `+0x164`,
/// feedback `+0x124`, cross-feed scalar `+0x15C`, tap block `+0x00..+0x2C`,
/// sidechain `+0x30..+0x44`, three delay lines at `+0x4C + 12*channel` with
/// indices `+0x7C..+0x84`, two filters at `+0xAC + 8*channel` with indices
/// `+0xCC`/`+0xD0`, envelopes at `+0x128 + 4*channel`, output planes at
/// `+0xE4 + 4*channel` and the two gains at `+0x170`/`+0x174`.
///
/// The `psq_st`/`mtfsf` prologue in the export only stores the incoming `f30`,
/// `f31` pair into two stack slots that are never read, so it has no modelled
/// effect; the two `ldexpf` calls after the loop are equally dead.
///
/// # Original
/// - Ghidra: `FUN_801a48f0` at `0x801a48f0` (1460 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801a48f0_FUN_801a48f0.c`
/// - Removed: the `bl 0x802DCDB8` (`__restgprlr_25`) epilogue; it only
///   restores the saved registers. The `bl 0x802DCD68` prologue is likewise
///   register bookkeeping and takes no part in the mix.
///
/// # Arguments
/// - `planes`: four-word vector of read/write cursor pointers (`r3`).
/// - `state`: mixer state (`r4`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the four tap, sidechain, delay, filter and output planes, the cursor
/// words and the envelope words of `state`.
///
/// # Safety
/// Every plane must hold at least 96 frames, every index must be inside its
/// ring, and `state` must be readable to `+0x178`.
///
/// # Confidence
/// medium - the loop, every store, the counter wrap and the four-way fold are
/// literal; the field roles and the `sdata2` constant roles are inferred from
/// [`fn_801a3880`], and the dead paired-single prologue is omitted.
pub unsafe fn fn_801a48f0(planes: u32, state: u32) {
    let s = state as usize;

    if read_u32(s + 0x13C) != 0 {
        write_u32(s + 0x13C, read_u32(s + 0x13C) & 0xFFFF_FFFD);
        return;
    }

    let extra_in = read_u32(s + 0x168);
    let extra_out = read_u32(s + 0x16C);

    let mut input = [
        read_u32(planes as usize) as usize,
        read_u32(planes as usize + 4) as usize,
        read_u32(planes as usize + 8) as usize,
        read_u32(planes as usize + 12) as usize,
    ];
    let mut extra = [0usize; 4];
    let mut aux = [0usize; 4];
    if extra_in != 0 {
        for channel in 0..4 {
            extra[channel] = read_u32(extra_in as usize + channel * 4) as usize;
        }
    }
    if extra_out != 0 {
        for channel in 0..4 {
            aux[channel] = read_u32(extra_out as usize + channel * 4) as usize;
        }
    }

    let limit = read_f32(SDA2_FX4_LIMIT);
    let blend = read_u32(s + 0x138) as f32;
    let mix = read_f32(SDA2_FX4_MIX);
    let direct_gain = read_u32(s + 0x164) as f32;
    let feedback = read_u32(s + 0x124) as f32;
    let cross = read_f32(SDA2_FX4_FEED) * read_u32(s + 0x15C) as f32;
    let delay_bias = read_f32(SDA2_FX4_DELAY);
    let offset = wave90_read_f64(SDA2_FX4_BIAS);
    let out_gain = read_u32(s + 0x170) as f32;
    let aux_gain = read_u32(s + 0x174) as f32;

    for _ in 0..0x60 {
        let mut acc = [0f32; 4];

        for channel in 0..4usize {
            let mut raw = read_i32(input[channel]);
            if extra_in != 0 {
                raw = raw.wrapping_add(read_i32(extra[channel]));
                extra[channel] += 4;
            }
            let mut sample = (((raw as u32) ^ 0x8000_0000) as f64 - offset) as f32;

            let base = read_u32(s + channel * 4) as usize;
            let tap_index_0 = read_u32(s + 0x10) as usize;
            let tap_index_1 = read_u32(s + 0x14) as usize;
            let tap_index_2 = read_u32(s + 0x18) as usize;
            let gain_0 = read_u32(s + 0x24) as f32;
            let tap_0 = read_f32(base + tap_index_0 * 4);
            let gain_1 = read_u32(s + 0x28) as f32;
            let tap_1 = read_f32(base + tap_index_1 * 4);
            let gain_2 = read_u32(s + 0x2C) as f32;
            let tap_2 = read_f32(base + tap_index_2 * 4);
            write_f32(base + tap_index_2 * 4, sample);

            if read_u32(s + 0x44) != 0 {
                let plane = read_u32(s + 0x30 + channel * 4) as usize;
                let index = read_u32(s + 0x40) as usize;
                let previous = read_f32(plane + index * 4);
                write_f32(plane + index * 4, sample);
                sample = previous;
            }
            let value = sample;

            let delay_plane_0 = read_u32(s + 0x4C + channel * 12) as usize;
            let delay_index_0 = read_u32(s + 0x7C) as usize;
            let delay_0 = read_f32(delay_plane_0 + delay_index_0 * 4);
            write_f32(
                delay_plane_0 + delay_index_0 * 4,
                value + delay_0 * read_u32(s + 0xA0) as f32,
            );

            let delay_plane_1 = read_u32(s + 0x50 + channel * 12) as usize;
            let delay_index_1 = read_u32(s + 0x80) as usize;
            let delay_1 = read_f32(delay_plane_1 + delay_index_1 * 4);
            write_f32(
                delay_plane_1 + delay_index_1 * 4,
                value + delay_1 * read_u32(s + 0xA4) as f32,
            );

            let delay_plane_2 = read_u32(s + 0x54 + channel * 12) as usize;
            let delay_index_2 = read_u32(s + 0x84) as usize;
            let delay_2 = read_f32(delay_plane_2 + delay_index_2 * 4);
            write_f32(
                delay_plane_2 + delay_index_2 * 4,
                value + delay_2 * read_u32(s + 0xA8) as f32,
            );

            let filter_plane_0 = read_u32(s + 0xAC + channel * 8) as usize;
            let filter_index_0 = read_u32(s + 0xCC) as usize;
            let filter_0 = read_f32(filter_plane_0 + filter_index_0 * 4);
            let sum = delay_bias + delay_0 + delay_1 + delay_2 + filter_0 * feedback;
            write_f32(filter_plane_0 + filter_index_0 * 4, sum);

            let filter_plane_1 = read_u32(s + 0xB0 + channel * 8) as usize;
            let filter_index_1 = read_u32(s + 0xD0) as usize;
            let filter_1 = read_f32(filter_plane_1 + filter_index_1 * 4);
            let filtered = (filter_0 - sum * feedback) + filter_1 * feedback;
            write_f32(filter_plane_1 + filter_index_1 * 4, filtered);

            let envelope = (limit - blend) * (filter_1 - filtered * feedback)
                + blend * read_u32(s + 0x128 + channel * 4) as f32;
            write_u32(s + 0x128 + channel * 4, envelope as i32 as u32);

            let out_plane = read_u32(s + 0xE4 + channel * 4) as usize;
            let out_index = read_u32(s + 0xF4 + channel * 4) as usize;
            let out_previous = read_f32(out_plane + out_index * 4);
            let out_value = envelope + out_previous * feedback;
            write_f32(out_plane + out_index * 4, out_value);

            let next = out_index.wrapping_add(1);
            if read_u32(s + 0x104 + channel * 4) as usize <= next {
                write_u32(s + 0xF4 + channel * 4, 0);
            } else {
                write_u32(s + 0xF4 + channel * 4, next as u32);
            }

            acc[channel] = (out_previous - out_value * feedback) * mix * direct_gain
                + gain_2 * tap_2
                + gain_0 * tap_0
                + gain_1 * tap_1;
        }

        let mono = acc[0] + (acc[3] + acc[1] + acc[2]) * cross;
        let mid = acc[1] + (acc[3] + acc[0] + acc[2]) * cross;
        let lower = acc[2] + (acc[3] + acc[0] + acc[1]) * cross;
        let fourth = acc[3] + (acc[2] + acc[0] + acc[1]) * cross;

        let out_0 = input[0];
        let out_1 = input[1];
        let out_2 = input[2];
        let out_3 = input[3];
        input[0] += 4;
        input[1] += 4;
        input[2] += 4;
        input[3] += 4;

        write_u32(out_0, (mono * out_gain) as i32 as u32);
        write_u32(out_1, (mid * out_gain) as i32 as u32);
        write_u32(out_2, (lower * out_gain) as i32 as u32);
        write_u32(out_3, (fourth * out_gain) as i32 as u32);

        if extra_out != 0 {
            write_u32(aux[0], (mono * aux_gain) as i32 as u32);
            write_u32(aux[1], (mid * aux_gain) as i32 as u32);
            write_u32(aux[2], (lower * aux_gain) as i32 as u32);
            write_u32(aux[3], (fourth * aux_gain) as i32 as u32);
            aux[0] += 4;
            aux[1] += 4;
            aux[2] += 4;
            aux[3] += 4;
        }

        wave101_bump(s, 0x10, 0x1C);
        wave101_bump(s, 0x14, 0x1C);
        wave101_bump(s, 0x18, 0x1C);
        if read_u32(s + 0x44) != 0 {
            wave101_bump(s, 0x40, 0x44);
        }
        wave101_bump(s, 0x7C, 0x88);
        wave101_bump(s, 0x80, 0x8C);
        wave101_bump(s, 0x84, 0x90);
        wave101_bump(s, 0xCC, 0xD4);
        wave101_bump(s, 0xD0, 0xD8);
    }
}

/// `0xCC005012` - DSP audio-DMA control halfword (written `0x0043`).
const DSP_DMA_CONTROL_5012: usize = 0xCC00_5012;
/// `0xCC005020`/`0xCC005024`/`0xCC005028` - the three DSP DMA words the reset
/// sequence publishes (`0x100`, `0`, `0x20`).
const DSP_DMA_WORD_5020: usize = 0xCC00_5020;
const DSP_DMA_WORD_5024: usize = 0xCC00_5024;
const DSP_DMA_WORD_5028: usize = 0xCC00_5028;

/// Reloads the `0x80`-byte segment at `0x81000000` from the boot block and
/// restarts the DSP.
///
/// When the machine-configuration word at `r13 - 0x5048` is zero the function
/// first re-runs the mode setup [`fn_801abf60`] with mode 1. It then copies
/// `0x80` bytes from `0x81000000` down to `arena_low - 0x80`, copies
/// `0x80332770` over `0x81000000`, flushes that range through `0x801AC470`,
/// runs the full DSP reset handshake (control `0x0043`, halt `0x08AC`, mailbox
/// flush, `0x100`/`0`/`0x20` DMA words, two `0x892`-tick waits, the
/// `0x800`/`0x400`/`0x4` control clears and the final `0x08AC`+start-bit
/// pulse), and finally copies the `0x80` bytes back into `0x81000000`.
///
/// # Original
/// - Ghidra: `FUN_801ac180` at `0x801ac180` (464 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ac180_FUN_801ac180.c`
/// - `// observed:` the shipped words `0x801AC1D8..0x801AC348` carry the whole
///   second half that the export dropped as eighteen "unreachable" blocks:
///   the `0xCC005012`/`0xCC00500A`/`0xCC005000`/`0xCC005020..28` writes, two
///   mailbox-busy polls, the two `0x801B5FA0` delays and the three control
///   clears. The function returns through `bclr` at `0x801AC34C`.
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `0x81000000..0x81000080`, the DSP MMIO block at `0xCC005000`, and
/// may rewrite the mode register; flushes the data cache for the segment.
///
/// # Safety
/// Boot-time only; `0x81000000` must be mapped writable, the arena word live
/// and the DSP registers present.
///
/// # Confidence
/// high - every instruction in the 464-byte extent is represented literally.
pub unsafe fn fn_801ac180() {
    if read_u32(SDA92_MACHINE_FLAG) == 0 {
        fn_801abf60(1);
    }

    let arena_low = fn_801abe80();
    platform::call3(
        FN_80004364,
        arena_low.wrapping_sub(0x80),
        BOOT_SEGMENT_DST as u32,
        0x80,
    );
    platform::call3(
        FN_80004364,
        BOOT_SEGMENT_DST as u32,
        BOOT_SEGMENT_SRC as u32,
        0x80,
    );
    platform::call2(FN_801AC470, BOOT_SEGMENT_DST as u32, 0x80);

    // 0x801AC1D8..0x801AC1F0: DMA control 0x0043, then halt the DSP and raise
    // the start bit until it self-clears.
    write_u16(DSP_DMA_CONTROL_5012, 0x0043);
    write_u16(DSP_CONTROL_STATUS, 0x08AC);
    write_u16(DSP_CONTROL_STATUS, read_u16(DSP_CONTROL_STATUS) | 1);
    while read_u16(DSP_CONTROL_STATUS) & 1 != 0 {
        core::hint::spin_loop();
    }

    // 0x801AC204..0x801AC220: clear the mailbox and wait for its busy bit.
    write_u16(DSP_MAILBOX, 0);
    while read_u16(DSP_MAILBOX_STATUS) & 0x8000 != 0 {
        core::hint::spin_loop();
    }

    // 0x801AC224..0x801AC254: publish the three DMA words and wait for the
    // control bit 0x20 to come back, then write the sampled value back.
    write_u32(DSP_DMA_WORD_5020, 0x100);
    write_u32(DSP_DMA_WORD_5024, 0);
    write_u32(DSP_DMA_WORD_5028, 0x20);
    let mut control = read_u16(DSP_CONTROL_STATUS);
    while control & 0x20 == 0 {
        core::hint::spin_loop();
        control = read_u16(DSP_CONTROL_STATUS);
    }
    write_u16(DSP_CONTROL_STATUS, control);

    // 0x801AC25C..0x801AC270: hold for at least 0x892 timebase ticks.
    let start = call0_u32(FN_801B5FA0);
    while (call0_u32(FN_801B5FA0).wrapping_sub(start) as i32) < 0x892 {
        core::hint::spin_loop();
    }

    // 0x801AC274..0x801AC2A8: the same three DMA words and the same 0x20 wait.
    write_u32(DSP_DMA_WORD_5020, 0x100);
    write_u32(DSP_DMA_WORD_5024, 0);
    write_u32(DSP_DMA_WORD_5028, 0x20);
    let mut control = read_u16(DSP_CONTROL_STATUS);
    while control & 0x20 == 0 {
        core::hint::spin_loop();
        control = read_u16(DSP_CONTROL_STATUS);
    }
    write_u16(DSP_CONTROL_STATUS, control);

    // 0x801AC2AC..0x801AC2E8: clear 0x800, wait for 0x400 to clear, clear 0x4,
    // then wait for the mailbox busy bit to come back.
    write_u16(DSP_CONTROL_STATUS, read_u16(DSP_CONTROL_STATUS) & !0x800);
    while read_u16(DSP_CONTROL_STATUS) & 0x400 != 0 {
        core::hint::spin_loop();
    }
    write_u16(DSP_CONTROL_STATUS, read_u16(DSP_CONTROL_STATUS) & !0x4);
    while read_u16(DSP_MAILBOX_STATUS) & 0x8000 == 0 {
        core::hint::spin_loop();
    }

    // 0x801AC2EC..0x801AC320: raise bit 0x4, rewrite the halt word, raise the
    // start bit and wait for it to clear.
    write_u16(DSP_CONTROL_STATUS, read_u16(DSP_CONTROL_STATUS) | 0x4);
    write_u16(DSP_CONTROL_STATUS, 0x08AC);
    write_u16(DSP_CONTROL_STATUS, read_u16(DSP_CONTROL_STATUS) | 1);
    while read_u16(DSP_CONTROL_STATUS) & 1 != 0 {
        core::hint::spin_loop();
    }

    // 0x801AC324..0x801AC348: copy the patched segment back into place.
    let arena_low = fn_801abe80();
    platform::call3(
        FN_80004364,
        BOOT_SEGMENT_DST as u32,
        arena_low.wrapping_sub(0x80),
        0x80,
    );
}

/// Resumes an `OSContext` after patching its saved link register and MSR bit.
///
/// If the saved LR at `+0x198` points strictly inside the interrupt wrapper
/// `0x801B1140..0x801B114C`, it is replaced by the wrapper's entry so the
/// resume re-enters the normal entry point. Bit 1 of the state halfword at
/// `+0x1A2` is then cleared, and the function returns the saved `+0xC`/`+0x10`
/// pair.
///
/// # Original
/// - Ghidra: `FUN_801ace30` at `0x801ace30` (216 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ace30_FUN_801ace30.c`
/// - `// observed:` `returnFromInterrupt(in_MSR & 0x9000, ctx[0x19C])` between
///   the two patches and the doubleword load.
///
/// # Arguments
/// - `context`: `OSContext`-shaped block; `+0x198` LR, `+0x19C` MSR,
///   `+0x1A2` state halfword, `+0xC`/`+0x10` the value pair.
///
/// # Returns
/// The 64-bit value formed by the words at `+0xC` (high) and `+0x10` (low).
///
/// # Side effects
/// May rewrite `+0x198` and clears bit 1 of `+0x1A2`.
///
/// # Safety
/// `context` must be a live, writable context block.
///
/// # Confidence
/// medium - the two patches and the returned pair are literal; the `rfi` and
/// the MSR composition are not expressible here and are omitted, so this body
/// is `partial`.
pub unsafe fn fn_801ace30(context: u32) -> u64 {
    let c = context as usize;
    let saved_lr = read_u32(c + 0x198);

    if saved_lr > FN_801B1140 as u32 && saved_lr < 0x801B_114C {
        write_u32(c + 0x198, FN_801B1140 as u32);
    }
    if read_u16(c + 0x1A2) & 2 != 0 {
        write_u16(c + 0x1A2, read_u16(c + 0x1A2) & 0xFFFD);
    }

    // partial: the original finishes with `returnFromInterrupt(MSR & 0x9000,
    // ctx[0x19C])`, which has no Rust form. The saved result pair is returned.
    ((read_u32(c + 0x0C) as u64) << 32) | read_u32(c + 0x10) as u64
}

/// Probes for and executes an alternative boot image over IOS.
///
/// The function installs the two arena bounds, opens the IOS device, issues the
/// first ioctl with a null buffer and, when the caller's flag at `local_18[0]`
/// still reads 1, allocates `0xE0` bytes, repeats the ioctl with that buffer and
/// calls the read/write half. If every step succeeds the routine never returns.
///
/// # Original
/// - Ghidra: `FUN_801ae770` at `0x801ae770` (200 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801ae770_FUN_801ae770.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing on the failure paths; the success path spins.
///
/// # Side effects
/// Writes the arena words, the `local_18[0]` flag, the IOS descriptor state and
/// the `0xE0`-byte transfer buffer.
///
/// # Safety
/// Boot-time only; the IOS device and the arena must be usable.
///
/// # Confidence
/// medium - every call, the flag test and the terminal loop are literal; the
/// callee roles come from the translated `runtime::dvd` bodies.
pub unsafe fn fn_801ae770() {
    let mut flag = [1u32; 5];

    fn_801abf10(EXEC_ARENA_LOW);
    fn_801abee0(EXEC_ARENA_HIGH);

    let mut status = call0_u32(FN_801D6230);
    if status == 0 {
        status = platform::call4(
            FN_801D6380,
            1,
            2,
            0,
            flag.as_mut_ptr() as *mut u32 as u32,
        );
        if flag[0] == 1 && status == 0 {
            let buffer = fn_801abf20(0xE0, 0x20);
            status = platform::call4(
                FN_801D6380,
                1,
                2,
                buffer,
                flag.as_mut_ptr() as *mut u32 as u32,
            );
            if status == 0 {
                status = platform::call3(FN_801D62E0, 1, 2, buffer);
                if status == 0 {
                    loop {
                        core::hint::spin_loop();
                    }
                }
            }
        }
    }
}

/// Boot hand-off: resets the video/DI paths, waits for the disc, installs the
/// `0x8038E600` context and switches stacks into `0x801AF7C0`.
///
/// The flow is: disable interrupts, take the scheduler lock, install and clear
/// the boot context, halt the DSP through [`fn_801ac350`], run the video and DI
/// reset helpers, poll the DI sequence word until it advances, wait for the
/// power callbacks or a `bus_clock / 4000 * 1000` tick deadline, unlock EXI
/// channel 0, wait for `0xCD00680C` bit 0 to clear, install JAI slot 8, drain
/// the VI FIFO, move the arena to `0x81400000`, save the incoming
/// `r3`/`r4`/`r5`, and switch stacks to `0x801AF7C0`.
///
/// # Original
/// - Ghidra: `FUN_801af5d4` at `0x801af5d4` (484 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801af5d4_FUN_801af5d4.c`
/// - `// observed:` the `0x802DCD68` prologue saves the incoming `r3`/`r4`,
///   which are stored to `0x8038E8C8`/`0x8038E8CC` at the end, and the last
///   call is `0x801ACF20(0x801AF7C0, arena_low)`.
/// - Removed: the `bl 0x802DCDB4` (`__restgprlr_24`) epilogue; it only
///   restores the saved registers.
///
/// # Arguments
/// - `param_1`, `param_2`: the incoming `r3`/`r4` pair saved for
///   `0x801AF7C0`.
/// - `param_3`: the word stored at `0x8038E8D0`.
///
/// # Returns
/// Nothing; the stack switch ends the original frame.
///
/// # Side effects
/// Resets the video/DI/DSP paths, writes the three boot globals, moves the
/// arena bound and clears the boot context.
///
/// # Safety
/// Boot-time only; every OS helper must be callable and the context block must
/// be writable.
///
/// # Confidence
/// high - every call, the saved `r3`/`r4` pointers, the 64-bit
/// `0x801B5F80` comparison against `([0x800000F8]/4000)*1000`, the DI poll, the
/// two `0x801ABEE0` operands (`[0x80003110]` or `[0x80000038]`) and the
/// `0x802DCD68` register save are literal.
pub unsafe fn fn_801af5d4(param_1: u32, param_2: u32, param_3: u32) {
    platform::call0(FN_801B1140);
    platform::call0(FN_801B4B70);
    platform::call1(FN_801ACF80, BOOT_CONTEXT);
    platform::call1(FN_801ACD40, BOOT_CONTEXT);
    fn_801ac350();
    platform::call0(FN_801BC7A0);
    platform::call1(FN_801B1590, 0x80);
    platform::call1(FN_801BDE50, 1);
    platform::call0(FN_801BDCB0);
    platform::call1(FN_801BC3E0, 0);
    platform::call1(FN_801BC430, 0);
    platform::call0(FN_801B1160);

    // observed: poll the DI sequence word until it advances by at least one.
    let start = call0_u32(FN_801BDED0) as i32;
    loop {
        let now = call0_u32(FN_801BDED0) as i32;
        if now.wrapping_sub(start) >= 1 {
            break;
        }
    }

    // inferred: continue while the elapsed time is below the deadline
    // `bus_clock / 4000 * 1000` ticks, or until 0x801B3360 reports a failure.
    let start_time = platform::call_u64(FN_801B5F80);
    let deadline = (read_u32(OS_BUS_CLOCK) / 4000).wrapping_mul(1000) as u64;
    let mut status;
    loop {
        status = platform::call2(FN_801B3360, 0, 0);
        if status != 0 {
            break;
        }
        let now = platform::call_u64(FN_801B5F80);
        if now.wrapping_sub(start_time) >= deadline {
            break;
        }
    }

    // unknown: the export prints the interrupt-disable helper here with the
    // loop's last result; the matching restore token is not recovered.
    platform::call1(FN_801B1140, status);
    platform::call2(FN_801B3360, 1, 0);
    platform::call2(FN_801B91D0, 0, 0);
    platform::call2(FN_801B91D0, 2, 0);

    loop {
        let locked = platform::call3(FN_801B9D70, 0, 1, 0);
        if locked != 0 {
            break;
        }
        platform::call1(FN_801B8F50, 0);
        platform::call1(FN_801B96F0, 0);
        platform::call1(FN_801B9E70, 0);
    }
    platform::call1(FN_801B9E70, 0);

    while read_u32(DI_CONTROL_WORD) & 1 == 1 {}

    fn_801ab020(8, BOOT_JAI_RECORD);
    platform::call0(FN_801C4CE0);
    fn_801abf10(BOOT_ARENA_LOW);
    let requested = read_u32(BOOT_MEM_SIZE_FLAG);
    if requested == 0 {
        fn_801abee0(read_u32(BOOT_SIM_MEM_SIZE));
    } else {
        // observed: the else arm enters 0x801ABEE0 with r3 still holding
        // `[0x80000038]`; the export prints the call with no argument.
        fn_801abee0(requested);
    }

    // observed: `lwz r0,0(r27)` / `lwz r0,0(r28)` -- the pair saved at the top
    // are *pointers*, so the words they address are what the globals receive.
    write_u32(BOOT_SAVED_PAIR_HI, read_u32(param_1 as usize));
    write_u32(BOOT_SAVED_PAIR_LO, read_u32(param_2 as usize));
    write_u32(BOOT_SAVED_ARG, param_3);

    let arena_low = fn_801abe80();
    platform::call2(FN_801ACF20, FN_801AF7C0 as u32, arena_low);
}

