const SDA2_BOOT_LOW: usize = SDA2_BASE - 0x4FAC;
const SDA2_BOOT_BASE: usize = SDA2_BASE - 0x4FB0;
const SDA2_BOOT_COEF_R: usize = SDA2_BASE - 0x4FA8;
const SDA2_BOOT_COEF_G: usize = SDA2_BASE - 0x4FA4;
const SDA2_BOOT_COEF_B: usize = SDA2_BASE - 0x4FA0;
const SDA2_BOOT_OFFSET: usize = SDA2_BASE - 0x4F9C;
const SDA2_BOOT_U_R: usize = SDA2_BASE - 0x4F98;
const SDA2_BOOT_U_G: usize = SDA2_BASE - 0x4F94;
const SDA2_BOOT_U_B: usize = SDA2_BASE - 0x4F90;
const SDA2_BOOT_V_G: usize = SDA2_BASE - 0x4F8C;
const SDA2_BOOT_V_R: usize = SDA2_BASE - 0x4F88;
const SDA2_BOOT_HIGH_FILL: usize = SDA2_BASE - 0x4F84;
const SDA2_BOOT_HIGH_INK: usize = SDA2_BASE - 0x4F80;

/// Waits for one of the shared DVD/exec callback words and aborts on a status
/// other than `1`.
///
/// The original prints the same `OSExec(): Failed to exec` line with the source
/// line of the wait as the third argument, then enters the panic path.
///
/// # Safety
/// `state_word` must be the callback word the matching read path writes.
#[inline]
unsafe fn exec_wait(state_word: usize, line: u32) {
    while read_u32(state_word) == 0 {}
    if read_u32(state_word) != 1 {
        report3(STR_EXEC_FAILED, read_u32(state_word), line);
        platform::call0(FN_801B3B80);
    }
}

/// Queues one DVD transfer and polls the descriptor until it retires.
///
/// `0x801CECC0` fills the six-word descriptor, then `0x801CEE90` is polled
/// three times per iteration: the first result is only a zero test, the second
/// must be at most 2 and the third must not be negative.
///
/// # Safety
/// `dst..dst+len` must be writable, `len` a multiple of four and `offset` a
/// valid disc offset in the unit the caller expects.
#[inline]
unsafe fn dvd_transfer(dst: u32, len: u32, offset: u32) {
    let mut descriptor = [0u32; 0xC];
    platform::call6(
        FN_801CECC0,
        descriptor.as_mut_ptr() as u32,
        dst,
        len,
        offset,
        0,
        0,
    );
    loop {
        if platform::call1(FN_801CEE90, descriptor.as_mut_ptr() as u32) == 0 {
            break;
        }
        let state = platform::call1(FN_801CEE90, descriptor.as_mut_ptr() as u32);
        if state > 2 {
            platform::call0(FN_801B3B80);
        }
        let code = platform::call1(FN_801CEE90, descriptor.as_mut_ptr() as u32) as i32;
        if code < 0 {
            platform::call0(FN_801B3B80);
        }
    }
}

/// Returns the cached DVD chunk size in words, probing the drive once.
///
/// The first call takes the `0x910` default when the drive reports no buffer
/// size; otherwise it queues a 0x40-byte probe and uses
/// `(reported_size + probe[0x38]) >> 2`. The result is cached in
/// `r13 - 0x4FDC`.
///
/// # Safety
/// Boot-time only; the arena and the DVD queue must be usable.
unsafe fn exec_chunk_size() -> u32 {
    let mut chunk = read_u32(OS_EXEC_CHUNK);
    if chunk == 0 {
        let reported = read_u32(OS_EXEC_CHUNK_BYTES);
        if reported == 0 {
            chunk = 0x910;
            write_u32(OS_EXEC_CHUNK, chunk);
        } else {
            let probe = fn_801abf20(0x40, 0x20);
            dvd_transfer(probe, 0x40, reported >> 2);
            chunk = reported.wrapping_add(read_u32(probe as usize + 0x38)) >> 2;
            write_u32(OS_EXEC_CHUNK, chunk);
        }
    }
    chunk
}

/// Converts one boot colour word into the `[Y, U, V, 0]` byte record used by
/// the framebuffer fill and the font blitter.
///
/// The three channel bytes are taken at `+8`, `+24` and `+16` of `color` (that
/// is `R`, `G`, `B` in the `0x00RRGGBB` the hand-off saved), converted through
/// the thirteen `sdata2` coefficients and clamped between [`SDA2_BOOT_LOW`] and
/// the two separate upper limits (`0x4F84` for the fill, `0x4F80` for the ink).
///
/// # Safety
/// None; the coefficient words must be readable, which they are in the target
/// image.
unsafe fn boot_yuv(color: u32) -> u32 {
    let low = read_f32(SDA2_BOOT_LOW);
    let base = read_f32(SDA2_BOOT_BASE);
    let r = ((color >> 8) & 0xFF) as f32;
    let g = ((color >> 24) & 0xFF) as f32;
    let b = ((color >> 16) & 0xFF) as f32;
    let offset = read_f32(SDA2_BOOT_OFFSET);

    let y = base
        + low
        + read_f32(SDA2_BOOT_COEF_R) * r
        + read_f32(SDA2_BOOT_COEF_G) * g
        + read_f32(SDA2_BOOT_COEF_B) * b;
    let u = base + offset
        + read_f32(SDA2_BOOT_U_R) * r
        + (read_f32(SDA2_BOOT_U_G) * g - read_f32(SDA2_BOOT_U_B) * b);
    let v = base + offset
        + ((read_f32(SDA2_BOOT_U_R) * g - read_f32(SDA2_BOOT_V_G) * b)
            - read_f32(SDA2_BOOT_V_R) * r);

    let y = clamp_band(y, read_f32(SDA2_BOOT_HIGH_FILL), low);
    let u = clamp_band(u, read_f32(SDA2_BOOT_HIGH_INK), low);
    let v = clamp_band(v, read_f32(SDA2_BOOT_HIGH_INK), low);
    (((y as i32) as u8 as u32) << 24)
        | (((u as i32) as u8 as u32) << 16)
        | (((v as i32) as u8 as u32) << 8)
}

/// Clamps `value` into `[lower, upper]` using the branch shape the compiler
/// emitted (test against the upper bound first, then against the lower one).
#[inline]
fn clamp_band(value: f32, upper: f32, lower: f32) -> f32 {
    if value <= upper {
        if value < lower {
            lower
        } else {
            value
        }
    } else {
        upper
    }
}

/// Restores the FPU state of one `OSContext` block.
///
/// If `context + 0x1A2` bit 0 is clear the routine returns untouched. Otherwise
/// it loads the saved FPSCR from `+0x190` with `mtfsf`, restores the 32 paired
/// singles from `+0x1C8 + 8i` with `psq_l` and the 32 doubles from `+0x90 + 8i`
/// with `lfd`.
///
/// # Original
/// - Ghidra: `FUN_801acad0` at `0x801ACAD0` (292 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801acad0_FUN_801acad0.c`
/// - `// observed:` the export is the `unaff_GQR0`/`ldexpf` expansion of the 32
///   paired-single loads; Ghidra's "return `context+0x98`" is just the restored
///   `f1`, not a real result.
///
/// # Arguments
/// - `context`: base of a readable `OSContext` block; Ghidra prints the base in
///   its eleventh pseudo-parameter, so the Rust signature takes it explicitly.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Replaces the live FPU register file with the saved one.
///
/// # Safety
/// `context` must be readable through `+0x2C8`, the saved state must be a valid
/// FPU snapshot, and `HID2[PS]` must be enabled for the `psq_l` block.
///
/// # Confidence
/// medium - the layout and the 32+32 slot streams are literal, but the paired
/// single loads cannot be expressed without the GQR/PS convention and Ghidra
/// leaves the register file unnamed.
